INSERT INTO empresa_infos (empresa_id, descricao, caminho_imagem) VALUES
(8, 'Manoelina da Silva Sousa é uma pessoa física domiciliada em Goianésia, Goiás. Sua atividade econômica não está classificada em ramo específico nos registros disponíveis.', NULL),
(16, 'A Planalto Blocos e Artefatos de Cimento Ltda é uma empresa do setor de construção civil sediada em Abadiânia, Goiás. Atua na fabricação de blocos, lajotas, meios-fios e demais artefatos de cimento utilizados em obras residenciais e comerciais na região.', NULL),
(17, 'A MC Máquinas Agrícolas Ltda está localizada em Goianésia, Goiás, e opera no segmento de máquinas e equipamentos voltados para o agronegócio. A empresa atende produtores rurais da região com comercialização e, possivelmente, manutenção de maquinário agrícola.', NULL),
(21, 'O ETE (Estação de Tratamento de Efluentes) de Goianésia é uma instalação gerenciada pela CODEGO — Companhia de Desenvolvimento Econômico de Goiás — no Distrito Agroindustrial do município. Tem a função de tratar os efluentes líquidos gerados pelas indústrias do distrito, garantindo o descarte ambientalmente adequado dos resíduos líquidos industriais.', NULL),
(31, 'A Petro-Graxa Indústria e Comércio de Produtos Automotivos é uma empresa química localizada em Inhumas, Goiás. Dedica-se à produção e comercialização de graxas lubrificantes, óleos e outros produtos químicos voltados para o setor automotivo e industrial.', NULL),
(34, 'A Prefeitura de Goianira é o órgão do Poder Executivo Municipal responsável pela administração pública do município de Goianira, no estado de Goiás. Compete a ela a prestação de serviços essenciais à população, como saúde, educação, infraestrutura e assistência social, além da gestão dos recursos e políticas públicas locais.', NULL),
(35, 'A NASA Indústria de Confecções Ltda – ME é uma microempresa do ramo de roupas, calçados e acessórios, sediada em Goianira, Goiás. Atua na fabricação de peças do vestuário, abastecendo o mercado local e regional.', NULL),
(38, 'A NJF Indústria e Comércio Ltda é uma empresa do setor alimentício com sede em Abadiânia, Goiás. Dedica-se à produção e comercialização de produtos alimentícios para o mercado regional, atuando no segmento de industrialização de alimentos.', NULL),
(40, 'A Power Breck Indústria e Comércio de Peças Ltda está localizada em Goianira, Goiás, e atua no segmento automobilístico. A empresa fabrica e comercializa peças e componentes para veículos, atendendo oficinas mecânicas e montadoras na região Centro-Oeste.', NULL),
(43, 'A Polo Injetados de Termoplásticos Eireli é uma indústria de materiais plásticos sediada no Distrito Agroindustrial de Goianira, Goiás. A empresa se especializa na injeção de peças e componentes termoplásticos sob encomenda, atendendo diferentes setores industriais da região.', NULL),
(52, 'A Passione Indústria e Comércio de Calçados Eireli é uma fabricante de calçados fundada em 2010 e sediada em Goianira, Goiás. Opera no polo calçadista do município, produzindo e comercializando calçados para o mercado nacional.', NULL),
(77, 'Francys Miller Alves da Silva é um profissional autônomo atuante no setor de construção civil em Goianira, Goiás. Presta serviços de edificação, reformas ou acabamentos na região.', NULL),
(82, 'A Fortaleza é uma empresa do agronegócio localizada em Goianésia, Goiás. Atua no setor agropecuário da região, que é reconhecida pela produção de cana-de-açúcar e pela agroindústria sucroenergética, podendo estar relacionada ao cultivo, beneficiamento ou comercialização de produtos agrícolas.', NULL),
(100, 'A Naturenge Engenharia Ambiental Ltda é uma empresa sediada em Porangatu, Goiás, que atua no segmento madeireiro com enfoque em engenharia ambiental. Presta serviços de manejo florestal, licenciamento ambiental e projetos relacionados ao uso sustentável de recursos madeireiros na região norte goiana.', NULL),
(108, 'A Power Blocks & Steel Indústria e Construtora é uma empresa do setor de construção civil sediada em Luziânia, Goiás. Atua na fabricação de blocos e estruturas metálicas (steel frame), oferecendo soluções construtivas para o mercado de obras residenciais e comerciais.', NULL),
(135, 'A Indústria e Comércio de Estofados Solar Ltda é uma empresa moveleira localizada em Rubiataba, Goiás. Fabrica sofás, poltronas, estofados e outros móveis com foco no mercado regional do interior goiano.', NULL),
(137, 'A Miranda Oliveira e Silva Comércio e Indústria de Móveis Ltda é uma empresa do setor moveleiro com sede em Rubiataba, Goiás. Produz e comercializa móveis para residências e estabelecimentos comerciais, atendendo a demanda local e regional.', NULL),
(139, 'Castilho Transporte é uma empresa transportadora sediada em Rubiataba, Goiás, atuando no transporte rodoviário de cargas na região centro-norte do estado. Presta serviços logísticos para produtores rurais, indústrias e comércios locais. Sua localização em Rubiataba posiciona a empresa como elo importante da cadeia logística do noroeste goiano.', NULL),
(140, 'A Estofados e Construtora Luar Ltda é uma empresa sediada em Rubiataba, Goiás, que atua tanto na fabricação de estofados quanto no setor da construção civil. Alia a produção de móveis estofados à execução de obras e serviços de construção na região.', NULL),
(143, 'A Central de Estofados é uma empresa sediada em Rubiataba, Goiás, especializada na fabricação e reforma de estofados para móveis residenciais e veículos. Atende clientes particulares, concessionárias e estabelecimentos comerciais da região. Oferece serviços de retapização, confecção de sofás, poltronas e bancos automotivos.', NULL),
(145, 'Elza Helena O. Santana é uma profissional autônoma que atua no setor têxtil em Uruaçu, Goiás. Desenvolve atividades ligadas à confecção ou beneficiamento de artigos têxteis na região.', NULL),
(146, 'A JR Produção de Alimentos Animal Ltda é uma empresa do agronegócio localizada em Uruaçu, Goiás. Atua na produção e comercialização de rações e suplementos alimentares para animais, atendendo criadores e produtores rurais da região norte de Goiás.', NULL),
(147, 'A Calbor - Caldeiraria Artefatos de Borracha é uma empresa metalúrgica e de artefatos de borracha instalada em Uruaçu (GO), no norte goiano. Atua na caldeiraria industrial e na fabricação de peças e componentes em borracha, prestando serviços à indústria local e regional.', NULL),
(148, 'A Urunaltica é uma empresa de serviços auxiliares ao transporte sediada em Uruaçu, Goiás. Presta apoio logístico e operacional ao setor de transportes, podendo atuar em serviços como armazenagem, despacho de cargas ou movimentação de mercadorias na região.', NULL),
(149, 'A Comercial Ad. F. Lima Ltda é uma empresa comercial do setor madeireiro sediada em Uruaçu, Goiás, atuando na compra e venda de madeiras serradas, beneficiadas e afins. Atende o mercado de construção civil e moveleiro da região centro-norte do estado. Sua localização em Uruaçu favorece o escoamento de produção para diversas cidades do interior goiano.', NULL),
(160, 'Mauro Cesar da Silva – ME é um microempreendedor individual atuante no setor de construção civil em Goianésia, Goiás. Presta serviços de obras, reformas e serviços correlatos para a população local.', NULL),
(162, 'A MM dos Santos Cozinhas Industriais Ltda é uma empresa do setor alimentício sediada em Uruaçu, Goiás. Atua no fornecimento de refeições ou na estruturação e operação de cozinhas industriais para empresas e coletividades da região norte goiana.', NULL),
(163, 'Juliana Miranda Teodoro Costa é uma profissional autônoma que atua no setor de construção civil em Uruaçu, Goiás. Presta serviços de edificação, reformas ou acabamentos para clientes na região.', NULL),
(170, 'Fábio Poloniato Tavares é um profissional autônomo do setor moveleiro em Uruaçu, Goiás. Atua na fabricação artesanal ou sob encomenda de móveis e peças em madeira para o mercado local.', NULL),
(175, 'A Pontual Etiquetas Ltda é uma empresa têxtil fundada em 2007 e sediada no Distrito Agroindustrial de Goianésia, Goiás. Fabrica etiquetas e rótulos para o setor de confecções e vestuário, atendendo indústrias têxteis e de calçados da região.', NULL),
(182, 'A Nortevidros Comércio de Vidros, Alumínios e Ferragens é uma empresa de vidraçaria localizada em Uruaçu, Goiás. Comercializa e instala vidros temperados, esquadrias de alumínio e ferragens para obras residenciais e comerciais no norte do estado.', NULL),
(185, 'Sidemar Ribeiro da Silva – ME é um microempreendedor individual do setor metalúrgico em Goianésia, Goiás. Presta serviços de fabricação, solda e beneficiamento de peças metálicas para clientes locais e da região.', NULL),
(189, 'A Oliveira e Vieira da Mota Ltda é uma empresa do agronegócio sediada em Goianésia, Goiás. Atua no comércio ou produção de insumos, commodities ou produtos agropecuários, inserida no contexto do agronegócio goiano.', NULL),
(205, 'Glauber de Oliveira Lopes é um profissional autônomo atuante no setor madeireiro em Goianésia, Goiás. Desenvolve atividades relacionadas ao comércio ou beneficiamento de madeira e produtos florestais na região.', NULL),
(207, 'A Neolatina Comércio e Indústria Farmacêutica S.A. é uma fabricante de medicamentos alopáticos para uso humano com sede no Distrito Agroindustrial de Anápolis (DAIA), fundada em 1966. Vinculada ao grupo Brainfarma, uma das maiores farmacêuticas da América Latina, a empresa integra o maior polo farmacêutico de Goiás e um dos mais importantes do Brasil. Produz medicamentos de referência e genéricos, distribuídos em todo o território nacional.', NULL),
(209, 'A BRG Brasil Geradores – EIRELI é uma empresa fundada em 2001, localizada no Distrito Agroindustrial de Anápolis (DAIA), especializada na fabricação de geradores de corrente contínua e alternada, peças e acessórios. Opera com grupos geradores que variam de 15 kVA a 1.760 kVA, atendendo clientes em todo o Brasil e na América Latina.', NULL),
(229, 'A Adubos Moema Indústria e Comércio Eireli é uma empresa do setor de agronegócio fundada em 1992, com unidade em Anápolis, Goiás, voltada ao comércio atacadista de fertilizantes, adubos e corretivos de solo. Com filiais em Goiânia (GO), Brasília (DF) e Luís Eduardo Magalhães (BA), a empresa atende produtores rurais e revendas agrícolas em várias regiões do país.', NULL),
(232, 'A BRG Brasil Geradores – EIRELI é uma fabricante de geradores elétricos instalada no Distrito Agroindustrial de Anápolis (DAIA), com mais de duas décadas de experiência no setor. Produz grupos geradores de corrente alternada e contínua com potência entre 15 kVA e 1.760 kVA para os mercados industrial, comercial e de serviços.', NULL),
(234, 'A Milena Indústria e Comércio de Calçados Ltda é uma fabricante de calçados sediada em Luziânia, Goiás. Produz e comercializa calçados femininos, masculinos e/ou infantis, atuando no mercado regional e nacional do segmento de roupas, calçados e acessórios.', NULL),
(237, 'A Isofrio Isolamentos Térmicos Ltda é uma indústria fabricante de máquinas e equipamentos de refrigeração e ventilação para uso industrial e comercial, localizada no Distrito Agroindustrial de Anápolis (DAIA). Fundada em 2005, a empresa fornece soluções em isolamento térmico e sistemas de refrigeração para indústrias, armazéns e instalações comerciais. Está sediada na Rua VP-R3 do DAIA, em Anápolis, Goiás.', NULL),
(239, 'A J.R.D. Indústria Farmacêutica Ltda, conhecida comercialmente como Uniphar, é uma fabricante de medicamentos alopáticos para uso humano com sede em Anápolis (GO). Fundada em 1987, integra o polo farmacêutico do Distrito Agroindustrial de Anápolis (DAIA), um dos maiores centros farmacêuticos do Brasil. A empresa emprega entre 250 e 499 pessoas e atua na produção e comercialização de medicamentos.', NULL),
(253, 'A ETS Importação e Exportação é uma empresa de comércio exterior localizada em Anápolis, Goiás, cidade que se destaca como um dos principais polos de importação do estado, abrigando a Estação Aduaneira de Interior (EADI) e o Porto Seco Centro-Oeste. A empresa atua na intermediação e operação de comércio internacional, aproveitando a posição estratégica de Anápolis entre Goiânia e Brasília. Opera no segmento de importação e exportação de mercadorias diversas.', NULL),
(254, 'A Cartonagem e Litografia Anapolina Ltda é uma empresa fundada em 1989 e instalada no Distrito Agroindustrial de Anápolis (DAIA), atuando na fabricação de embalagens e artefatos de papel e papelão. Produz caixas e embalagens de papelão microondulado para os setores alimentício, farmacêutico, de limpeza e de fast food.', NULL),
(257, 'A Nutrifort Indústria e Comércio de Produtos Agropecuários é uma empresa do agronegócio localizada em Mineiros, Goiás. Atua na produção e comercialização de rações, suplementos minerais e insumos para pecuária e agricultura, atendendo produtores rurais do sudoeste goiano.', NULL),
(260, 'A Recipel Indústria e Comércio de Insumos Reciclados Ltda é uma empresa de reciclagem com mais de 30 anos de atuação, sediada no DAIA em Anápolis, Goiás. Realiza coleta, triagem, classificação, enfardamento e comercialização de papel, plástico e isopor, atuando nos estados de Goiás, Mato Grosso, Tocantins e Pará.', NULL),
(265, 'A Thunder Bolt Indústria de Alimentos Ltda é uma fabricante de suplementos alimentares e alimentos especiais localizada no DAIA, em Anápolis, Goiás, com mais de 20 anos de mercado. Associada à Midway International Labs, produz suplementos proteicos e energéticos para o segmento de nutrição esportiva e saúde.', NULL),
(266, 'A Silveira e Canedo Ltda é uma empresa de comércio e indústria de madeiras localizada em Anápolis, Goiás, que opera sob o nome fantasia Coimar Indústria de Madeira. Fundada em 2005, atua na fabricação de esquadrias de madeira, portas e janelas para uso residencial, comercial e industrial.', NULL),
(267, 'A Midway Tecnologia de Alimentos Ltda, integrante do grupo Midway Labs, é uma das maiores produtoras de suplementos alimentares do Brasil e da América Latina, com unidade no Distrito Agroindustrial de Anápolis (DAIA). Fundada em 1991 nos EUA, a empresa transferiu sua produção para Anápolis, expandindo 50 vezes sua capacidade produtiva. Seu principal produto é o shake diet, comercializado sob a marca Diet Way, além de mais de 100 outros itens no portfólio.', NULL),
(268, 'A Marmoraria Limagran Ltda é uma empresa especializada no beneficiamento e comercialização de mármores e granitos, com sede no Distrito Agroindustrial de Anápolis (DAIA). Fundada em Anápolis (GO), oferece ampla variedade de pedras naturais e industrializadas nacionais e importadas, incluindo mármore, granito, quartzo e outras superfícies. Atende obras residenciais e empresariais, fornecendo revestimentos e tampos com instalação.', NULL),
(269, 'A Química Amparo Ltda é uma das maiores fabricantes brasileiras de produtos de limpeza doméstica, responsável pela linha Ypê. Fundada em 1950 com sede em Amparo (SP), inaugurou uma unidade fabril em Anápolis (GO) em 2010, com capacidade inicial de 10 milhões de litros por ano e cerca de 200 funcionários.', NULL),
(270, 'A M A Vieira Alimentos Eireli é uma empresa do setor alimentício sediada em Anápolis (GO), atuando na fabricação e comercialização de produtos alimentícios. Inserida no polo agroindustrial anapolino, a empresa se beneficia da localização estratégica da cidade para distribuição de alimentos no Centro-Oeste e demais regiões do Brasil.', NULL),
(271, 'O Super Posto e Churrascaria do DAIA Ltda é um estabelecimento que combina posto de combustíveis e restaurante de churrascaria, localizado na Via Principal do DAIA, em Anápolis, Goiás, desde 1984. Atende caminhoneiros, funcionários das indústrias e visitantes do distrito agroindustrial, sendo referência de refeição e abastecimento na região.', NULL),
(273, 'O Laboratório ERI Brasil International Ltda é uma empresa farmacêutica localizada em Anápolis (GO), inserida no polo farmoquímico do DAIA, o segundo maior polo farmacêutico do Brasil. Atua na produção e comercialização de produtos farmacêuticos, beneficiando-se da infraestrutura especializada e dos incentivos fiscais disponíveis para o setor na região.', NULL),
(274, 'A Metago (Metais de Goiás S/A) foi uma empresa pública do estado de Goiás criada em 1961 com o objetivo de realizar pesquisa mineral, lavra de minérios e fomentar o setor de mineração goiano. Após um longo período de declínio causado por crise de gestão e interferências políticas, teve seu processo de liquidação encerrado em 2022. Durante décadas, a Metago foi responsável pela política mineral do estado, deixando extenso acervo técnico sobre os recursos minerais de Goiás.', NULL),
(276, 'A Geolab Indústria Farmacêutica S/A é uma das principais farmacêuticas nacionais, fundada em 1999 e sediada no Distrito Agroindustrial de Anápolis (DAIA), um dos maiores polos farmacêuticos do Brasil. A empresa produz medicamentos genéricos, similares, OTCs, fitoterápicos e medicamentos hospitalares, com portfólio superior a 300 SKUs. É reconhecida como o terceiro maior produtor de colírios do Brasil e figura entre as 15 maiores empresas farmacêuticas do país.', NULL),
(278, 'A Irmãos Gravia Ltda foi uma empresa metalúrgica de Anápolis, Goiás, especializada na fabricação de esquadrias de metal, fundada em 1985. A empresa atuou no Distrito Industrial de Anápolis até seu encerramento voluntário em 1991, tendo dado origem à empresa sucessora Gravia Esquality Indústria Metalúrgica Ltda. Representou um dos primeiros empreendimentos metalúrgicos da família Gravia no polo industrial anapolino.', NULL),
(279, 'A Gravia Esquality Indústria Metalúrgica Ltda é uma empresa metalúrgica especializada na fabricação de esquadrias de metal, localizada no Distrito Agroindustrial de Anápolis (DAIA). Fundada em 1991, a empresa forneceu janelas, portas e estruturas metálicas para o mercado da construção civil. A empresa encontra-se em processo de recuperação judicial desde 2022, com situação cadastral inativa junto à Receita Federal.', NULL),
(280, 'O Posto Tabocão X Ltda é um posto de combustíveis localizado no Distrito Agroindustrial de Anápolis (DAIA), em Goiás, com funcionamento 24 horas. Fundado em 1981, oferece revenda de combustíveis para veículos automotores, além de estacionamento noturno e banheiros e chuveiros gratuitos para motoristas.', NULL),
(281, 'A Café Rancheiro Agro Industrial Ltda é uma torrefadora e moedora de café 100% arábica com certificação de qualidade ABIC, fundada em 1986 e sediada no DAIA, em Anápolis, Goiás. Comercializa seus produtos sob a marca Rancheiro, com linha tradicional e especial disponível em embalagens diversas para o varejo nacional.', NULL),
(288, 'A Cinco – Confiança Indústria e Comércio Ltda é uma empresa sediada no Distrito Agroindustrial de Anápolis (DAIA), fundada em 2002, atuante no comércio atacadista e na fabricação de instrumentos e materiais para uso médico-cirúrgico, hospitalar e laboratorial.', NULL),
(289, 'A Globo Metalúrgica Indústria e Comércio Ltda é uma empresa metalúrgica localizada em Anápolis, Goiás, atuante na fabricação de produtos metálicos para uso industrial e da construção civil. A empresa integra o polo metalúrgico do Distrito Agroindustrial de Anápolis, que concentra diversas indústrias do setor. Atende clientes da indústria regional com produtos manufaturados em metal.', NULL),
(290, 'A Soíma do Brasil Ind. e Com. de Equipamentos para Construção Ltda é fabricante, revendedora e locadora de gruas para a construção civil, com sede no DAIA em Anápolis, Goiás. Fundada em 2012 por parceiros portugueses e brasileiros, a empresa trouxe ao Brasil o know-how da SOIMA Cranes, marca portuguesa com 40 anos de experiência e presença em mais de 50 países.', NULL),
(294, 'A Involv Labels Ltda é uma indústria fabricante de embalagens, etiquetas, bulas e rótulos de alta qualidade, sediada no Distrito Agroindustrial de Anápolis (DAIA). Fundada em 2005, a empresa atende clientes dos setores farmacêutico, alimentício e industrial com soluções gráficas personalizadas. Em 2023, passou a integrar o grupo global de embalagens All4Labels Global Packaging Group, ampliando sua capacidade produtiva e presença de mercado.', NULL),
(295, 'A Aché Laboratórios Farmacêuticos S.A. é uma das maiores farmacêuticas nacionais do Brasil, com unidade industrial instalada no Distrito Agroindustrial de Anápolis (DAIA), voltada para a fabricação de medicamentos alopáticos para uso humano. A empresa possui cinco plantas industriais no país e conta com capital social superior a R$ 441 milhões.', NULL),
(297, 'A Pérola Ind. e Comércio de Prod. Alimentícios integra o Grupo Pérola, conglomerado alimentício com forte presença em Anápolis (GO). O grupo atua em industrialização, fracionamento, acondicionamento e distribuição atacadista de produtos alimentícios em geral. Possui balcões de venda em Anápolis e Goiânia, além de loja online, atendendo varejistas e consumidores finais da região.', NULL),
(298, 'O Rei dos Condimentos Indústria e Comércio Ltda é uma empresa especializada na fabricação de temperos, molhos, condimentos e especiarias, localizada no DAIA em Anápolis, Goiás. Com mais de 20 anos de mercado, diferencia-se por oferecer produtos sem glutamato monossódico, atendendo consumidores que buscam opções mais naturais.', NULL),
(299, 'A HS Manutenção Ind. e Transportes Ltda é uma empresa anápolitana que atua na prestação de serviços de manutenção industrial e transporte. Oferece serviços de manutenção preventiva e corretiva de máquinas e equipamentos industriais, além de soluções logísticas para indústrias da região. Anápolis, sendo um dos maiores parques industriais de Goiás, representa mercado consolidado para esse tipo de serviço.', NULL),
(300, 'A Caritas Estruturas Metálicas Ltda é uma empresa metalúrgica localizada em Anápolis, Goiás, atuante na fabricação e montagem de estruturas metálicas para a construção civil e industrial. Atende obras de galpões, coberturas, mezaninos e edificações industriais.', NULL),
(301, 'A GVPAR Participações e Investimentos Ltda é uma holding fundada em 2008, com sede em Goiás, que atua por meio de participações societárias em empresas de diferentes setores. A empresa possui filiais em Aparecida de Goiânia, Anápolis, Catalão e Rio Verde, operando sob o nome fantasia GVPAR Ambiental. Em Anápolis, mantém atividade relacionada à fabricação de embalagens plásticas no Distrito Industrial.', NULL),
(302, 'A J. Roberto Comércio Atacadista de Açúcar Ltda atua no comércio por atacado de açúcar, distribuindo o produto para o mercado interno. A empresa opera com foco em abastecer revendas, indústrias alimentícias e estabelecimentos comerciais. Está inserida no polo agroindustrial de Anápolis, cidade estratégica para o escoamento de produtos alimentícios no Centro-Oeste.', NULL),
(303, 'A XCX Transportes Eireli é uma empresa de transporte rodoviário de cargas sediada em Anápolis, Goiás. Atua no transporte de mercadorias aproveitando a posição estratégica da cidade como principal entroncamento rodoviário do Centro-Oeste, com fácil acesso às BRs 060, 153 e 414.', NULL),
(304, 'A Porto & Pereira Ltda é uma empresa de fornecimento de refeições corporativas localizada no Distrito Agroindustrial de Anápolis (DAIA), em Goiás. Atua principalmente no preparo e entrega de refeições para empresas da região industrial, operando sob o nome fantasia Arte Sabor Restaurante.', NULL),
(307, 'A Suprema Soluções para Transporte Ltda é uma empresa de transporte rodoviário de cargas com sede em Anápolis, Goiás. Atua no transporte e na logística de mercadorias, aproveitando a posição estratégica de Anápolis como entroncamento rodoviário do Centro-Oeste brasileiro.', NULL),
(308, 'A Bagolele Sorvetes Indústria e Comércio Ltda é uma das marcas mais tradicionais de sorvetes de Anápolis, Goiás, fundada em 1982. Com sede no DAIA e quatro unidades operacionais, fabrica sorvetes e outros produtos gelados, comercializando-os em lojas próprias e pontos de venda na cidade.', NULL),
(311, 'A Carta Industrial Produtos de Higiene e Limpeza S.A. é uma empresa de grande porte sediada no Distrito Agroindustrial de Anápolis (DAIA), com mais de duas décadas de atuação no mercado. Com capital social de R$ 76 milhões, a empresa atua na fabricação de produtos de higiene e limpeza para o mercado nacional.', NULL),
(312, 'A Michigan Cards do Brasil Ltda é uma empresa especializada na impressão e fabricação de cartões plásticos de segurança, como cartões de identificação, cartões magnéticos e documentos em plástico, com sede em Anápolis (GO). Fundada em 1999, a empresa atende clientes institucionais, empresas e órgãos públicos que demandam soluções em personalização e segurança de cartões. Opera com tecnologia de impressão de material de segurança.', NULL),
(313, 'A Bisnago Indústria de Embalagens Ltda é uma empresa fundada em 2008, localizada no Distrito Agroindustrial de Anápolis (DAIA), atuante na fabricação de embalagens metálicas para alimentos, bebidas e produtos químicos.', NULL),
(314, 'A Tetra Pet Ind. Com. Imp. e Exp. de Plásticos Ltda, conhecida como Tetrapet Embalagens, é uma fabricante de embalagens plásticas em PET e PVC localizada no DAIA, em Anápolis, Goiás. Fundada em 2004, seus produtos atendem indústrias dos segmentos alimentício, farmacêutico e de bebidas no mercado nacional e internacional.', NULL),
(315, 'A Delfire Arms (DFA Defense) é uma fabricante brasileira de armamentos fundada em 2016 e sediada em Anápolis, Goiás. Surgiu de uma parceria estratégica entre a Delfire — fabricante de extintores de incêndio — e a empresa eslovena Rex Firearms, e em 2022 inaugurou sua fábrica no Distrito Agroindustrial de Anápolis (DAIA), sendo a primeira nova autorização para fabricação de armas leves no Brasil em 80 anos.', NULL),
(316, 'A Aurobindo Pharma Indústria Farmacêutica Ltda é a subsidiária brasileira do grupo farmacêutico indiano Aurobindo Pharma, instalada no Distrito Agroindustrial de Anápolis (DAIA) desde 2001. A unidade fabrica medicamentos alopáticos para uso humano e produtos farmacoquímicos, integrando o segundo maior polo farmacêutico do Brasil.', NULL),
(317, 'A Tégula S.A. é a maior fabricante de telhas de concreto do Brasil, com mais de 45 anos de atuação no mercado e cinco fábricas no país, uma delas no Distrito Agroindustrial de Anápolis (DAIA), em Goiás. Detém cerca de 30% de participação no mercado de telhas de concreto e é integrante do Grupo Eternit, que a adquiriu em 2010.', NULL),
(319, 'A CMP - Companhia Metalgráfica Paulista é a mais antiga fabricante de latas de aço do Brasil, com cinco unidades espalhadas pelo país. A filial de Anápolis (GO), localizada no DAIA, tem capacidade de transformar 3 mil toneladas de aço por mês, produzindo embalagens metálicas para alimentos e produtos químicos, com certificações ISO 9001, 14001, 22000 e 45001.', NULL),
(321, 'A SM Empreendimentos Farmacêuticos Ltda é uma empresa do polo farmacêutico de Anápolis, Goiás, voltada à fabricação de produtos farmoquímicos. Com sede no DAIA e capital social de aproximadamente R$ 147 milhões, está associada ao Grupo Fagron, referência mundial em farmácia magistral e matérias-primas farmacêuticas.', NULL),
(323, 'A Fortlev Indústria e Comércio de Plásticos Ltda é a maior produtora de caixas d''água e reservatórios plásticos do Brasil, com unidade instalada no Distrito Agroindustrial de Anápolis (DAIA), em Goiás, em uma área de 50.000 m². Produz tanques e reservatórios de polietileno para armazenamento de água e tem forte atuação também no segmento de tubos e conexões de PVC.', NULL),
(324, 'A SIF Farmacêutica Eireli é uma empresa do setor farmacêutico com atuação em Anápolis, Goiás, cidade que concentra o segundo maior polo farmacêutico do Brasil. Inserida no DAIA, desenvolve atividades relacionadas à produção ou distribuição de produtos farmacêuticos.', NULL),
(327, 'A Metalúrgica Irmãos Ltda é uma empresa familiar com mais de 20 anos de tradição em Anápolis (GO), fundada em setembro de 2003. Sediada no Distrito Agroindustrial de Anápolis (DAIA), fabrica mais de 1.200 produtos, com destaque para painéis elétricos, caixas de passagem e padrões de entrada de energia. Atende distribuidoras, construtoras e empresas de toda a região.', NULL),
(328, 'A Fundição Almeida Ltda é uma empresa metalúrgica especializada em fundição e usinagem, sediada no Distrito Agroindustrial de Anápolis (DAIA), em Goiás. A empresa presta serviços de fundição de metais e tornearia, atendendo a indústria local e regional. Está localizada na Rua VP-RE, Quadra 6-A, do DAIA em Anápolis.', NULL),
(329, 'A Metalúrgica Dobra Aço Ltda, conhecida como Metalúrgica Dobraço, é uma empresa especializada na fabricação de estruturas metálicas, corte e dobra de chapas, localizada no DAIA em Anápolis (GO). Com fábrica moderna de 15.000 m², oferece também chapas xadrez, aço inox 304 e 405, perfis e outros produtos metálicos. Atende indústrias, construtoras e empresas de toda a região Centro-Oeste.', NULL),
(330, 'A Champion Farmoquímico Ltda é uma empresa fundada em 1993, instalada no Distrito Agroindustrial de Anápolis (DAIA), atuante na fabricação e atacado de produtos farmoquímicos para uso humano e veterinário. Integra o polo farmoquímico de Anápolis, um dos mais importantes do Brasil, exportando seus insumos para mais de dez países.', NULL),
(332, 'A JBS Tanques Indústria e Comércio é uma empresa fundada em 1986 e sediada no Distrito Agroindustrial de Anápolis, Goiás. Especializa-se na fabricação de tanques para transporte de produtos perigosos, reservatórios aéreos metálicos e veículos especiais, atendendo indústrias e transportadoras de todo o Brasil.', NULL),
(333, 'A Para-Fix Ind. e Com. de Fixadores de Metal Ltda, comercialmente conhecida como Para-Fix Parafusos e Fixadores, é uma empresa fundada em 1997, sediada no Distrito Agroindustrial de Anápolis (DAIA). Possui sede própria de 7.000 m², com equipamentos modernos para fabricação de parafusos, porcas e fixadores metálicos com precisão e durabilidade. Oferece soluções padronizadas e customizadas para diversas indústrias do país.', NULL),
(334, 'A Evangelista de Castro Dutos Plásticos Ltda é uma indústria fabricante de tubos e conexões de material plástico para uso na construção civil, sediada em Anápolis, Goiás. A empresa atua no fornecimento de dutos e acessórios plásticos destinados a instalações hidráulicas e de infraestrutura. Está registrada no Distrito Industrial de Anápolis com foco no mercado da construção civil goiano.', NULL),
(335, 'A Quality Ind. e Com. de Alimentos Ltda é uma indústria alimentícia localizada no DAIA, em Anápolis, Goiás, que atua na fabricação de produtos de panificação industrial. Opera sob o nome fantasia Sabor e Arte e produz alimentos para o mercado atacadista e varejista, com distribuição regional.', NULL),
(337, 'A MG Steckelberg Ind. Mecânica Industrial, registrada como Indústria Metalúrgica Steckelberg Ltda, é uma empresa de instalação e fabricação de máquinas e equipamentos industriais localizada em Anápolis (GO). Fundada em 1997, presta serviços de instalação de maquinário para o parque industrial anapolino e da região. A empresa é administrada por Marlete Gonçalves Steckelberg e opera com capital de R$ 100 mil.', NULL),
(338, 'A Fabbrica di Park Ltda é uma empresa sediada no Distrito Agroindustrial de Anápolis (DAIA), em Goiás, atuante na fabricação de brinquedos e jogos recreativos. Fundada em 2005, a empresa está registrada no CNAE de fabricação de outros brinquedos e jogos recreativos. Atende o mercado de entretenimento e lazer com produtos manufaturados no polo industrial anapolino.', NULL),
(339, 'A Brasil Engarrafamento de Álcool e Bebidas Alcoólicas Ltda é uma empresa do setor de bebidas instalada no Distrito Agroindustrial de Anápolis (DAIA). Atua no engarrafamento e no comércio atacadista de álcool etílico e bebidas alcoólicas, abastecendo distribuidores e parceiros comerciais da região centro-oeste.', NULL),
(340, 'A Pharma Express Ind Com e Operadora Logística Ltda é uma empresa anapolina fundada em 2009, sediada no Distrito Agroindustrial de Anápolis (DAIA), que combina atividades de armazenagem logística, industrialização de produtos químico-farmacêuticos e operação logística de cargas. A empresa possui múltiplas unidades no DAIA e atende o polo farmacêutico de Anápolis com serviços integrados de logística e distribuição de medicamentos.', NULL),
(341, 'O Chão Cerrado Restaurante Ltda é um restaurante localizado na Praça James Fanstone, em Anápolis (GO), especializado em culinária brasileira e goiana. O cardápio inclui pratos tradicionais do cerrado, como galinhada, feijão tropeiro e paçoca de carne.', NULL),
(342, 'A Perlen Packaging é uma empresa suíça e terceira maior fornecedora mundial de filmes revestidos para embalagens farmacêuticas. Inaugurou em 2018 sua primeira planta na América Latina no Distrito Agroindustrial de Anápolis (DAIA), em Goiás, produzindo filmes de PVC e PVC+PVDC utilizados na fabricação de blisteres por laboratórios farmacêuticos do Brasil e da região.', NULL),
(343, 'A Plentis Pharma Indústria, Comércio e Importação Ltda é uma empresa farmacêutica fundada em 2013 e sediada no Distrito Agroindustrial de Anápolis (DAIA), Goiás. Atua na fabricação de produtos químicos farmacêuticos, inserida no polo farmoquímico de Anápolis, o segundo maior polo farmacêutico do Brasil.', NULL),
(345, 'A Pharma Cluster Ind e Com Ltda é uma empresa farmacêutica localizada em Anápolis (GO), integrada ao polo farmacêutico do Distrito Agroindustrial de Anápolis (DAIA), o segundo maior polo farmoquímico do Brasil. Atua na fabricação e comercialização de produtos farmacêuticos, beneficiando-se da infraestrutura especializada e dos incentivos do setor disponíveis em Anápolis, que concentra mais de 20 indústrias farmacêuticas.', NULL),
(346, 'A Ciplan Cimento Planalto S.A. é uma empresa instalada no Distrito Agroindustrial de Anápolis (DAIA), atuante na fabricação e fornecimento de cimento, concreto e argamassa para a construção civil. Com décadas de operação no mercado, a empresa fornece materiais de construção para obras na região Centro-Oeste do Brasil.', NULL),
(347, 'A Pharmapet Indústria e Comércio Ltda é uma empresa sediada em Anápolis, Goiás, que atua na fabricação de produtos plásticos voltados ao segmento pet e veterinário. Produz embalagens, frascos e outros artefatos plásticos destinados à indústria de saúde animal e insumos agropecuários.', NULL),
(348, 'A Tubolar Ind. e Com. de Plástico Ltda é uma indústria de plásticos com sede no Distrito Agroindustrial de Anápolis (DAIA), fundada em 1975 e com quase cinco décadas de atuação. Fabrica embalagens e artefatos plásticos, atendendo empresas de diversos segmentos industriais e comerciais.', NULL),
(349, 'A Fortlev Indústria e Comércio de Plásticos Ltda é uma renomada fabricante nacional de caixas d''água de polietileno e produtos plásticos para construção civil, com unidade instalada no Distrito Agroindustrial de Anápolis (DAIA). A fábrica em Anápolis foi inaugurada para ampliar a capacidade de produção de reservatórios de água para o mercado centro-oeste. A Fortlev é reconhecida no Brasil pela qualidade de seus produtos para armazenamento de água e tubulações de PVC.', NULL),
(350, 'A Comercial Araguaia Auto Posto Ltda, conhecida como Posto Araguaia, é um posto de abastecimento de combustíveis localizado no Distrito Agroindustrial de Anápolis, Goiás. Fundada em 1987, atua no varejo de combustíveis automotivos, oferecendo gasolina, etanol e diesel. Está presente nos registros oficiais de preços de combustíveis do Estado de Goiás.', NULL),
(351, 'A Contelhas Pré-Moldados Indústria e Comércio Ltda, com nome fantasia Vibracom, foi uma fabricante de artefatos de cimento para construção civil, como lajes pré-moldadas, sediada no DAIA em Anápolis, Goiás. Fundada em 2009, a empresa encerrou suas atividades em 2023, tendo sido incorporada a outra empresa. Seu endereço estava na Viela VP 7E, no Distrito Agroindustrial de Anápolis.', NULL),
(353, 'A Tubomax Pré-Moldados Indústria e Comércio Ltda é uma fabricante de artefatos de concreto pré-moldado localizada no DAIA, em Anápolis, Goiás, figurando entre as três maiores do setor na cidade. Fundada em 2010, produz estruturas de concreto armado em série e sob medida.', NULL),
(355, 'A Conpostes Pré-Moldados Indústria e Comércio Ltda é uma empresa de construção civil sediada no Distrito Agroindustrial de Anápolis (DAIA), especializada na fabricação de peças pré-moldadas de concreto armado. Atende obras de construção civil, projetos industriais, comerciais e agropecuários com produtos estruturais de alta durabilidade.', NULL),
(358, 'A Móveis German Ind e Com Hoteis e Turismo Ltda é uma fabricante de móveis com predominância em madeira, com sede no Distrito Agroindustrial de Anápolis (DAIA). Fundada em 2006, atende o segmento hoteleiro e turístico com móveis planejados e seriados, além de atender outros clientes corporativos. Conta com aproximadamente 19 anos de operação e capital social de R$ 1,3 milhão.', NULL),
(360, 'A Inpar Indústria de Pré-Moldados e Artefatos Ltda é uma empresa da construção civil localizada no Distrito Agroindustrial de Anápolis (DAIA), em Goiás. Fabrica tubos de concreto, blocos, caixas de passagem, fossas sépticas, meio-fios e outros artefatos de cimento pré-moldados para uso em obras de infraestrutura e edificações.', NULL),
(361, 'A Alisul Alimentos S.A. é uma empresa com mais de 45 anos de história, fundada em São Leopoldo (RS) em 1979, com unidade instalada em Anápolis (GO) a partir do início dos anos 2000. Fabrica rações e alimentos completos para animais domésticos sob a marca Supra, com capacidade de atendimento nacional a partir do DAIA.', NULL),
(362, 'A Agro Cria Comércio e Indústria Ltda é uma empresa do setor de agronegócio instalada no Distrito Agroindustrial de Anápolis (DAIA). Atua no comércio e na industrialização de produtos voltados à produção agrícola e pecuária, atendendo produtores rurais da região centro-oeste.', NULL),
(364, 'A Massa Falida Sotave Centro Oeste S.A. representa o espólio em processo de liquidação judicial da empresa Sotave, que atuava no agronegócio na região de Anápolis, Goiás. A massa falida é administrada por um síndico/administrador judicial, responsável por liquidar os ativos e saldar as obrigações da empresa encerrada.', NULL),
(366, 'A Sologran Indústria e Comércio Ltda é uma empresa do setor de agronegócio localizada no DAIA, em Anápolis, Goiás, atuando na fabricação de fertilizantes fosfatados, nitrogenados, potássicos e compostos para uso agrícola e doméstico. Fundada em 1997, acumula quase três décadas de experiência no mercado de insumos agrícolas.', NULL),
(367, 'A Mexichem Brasil Indústria de Transformação Plástica Ltda é uma subsidiária da multinacional mexicana Orbia, atuante na fabricação de tubos e conexões de PVC para os setores de construção civil, infraestrutura e agricultura. Com unidade no Distrito Agroindustrial de Anápolis (DAIA) desde 2010, a empresa consolidou presença no mercado brasileiro integrando marcas como Amanco e Plastubos. Oferece soluções completas para saneamento, irrigação e construção.', NULL),
(368, 'A Cecrisa Revestimentos Cerâmicos S.A. é uma das maiores fabricantes de revestimentos cerâmicos do Brasil, com presença em Anápolis por meio de uma unidade industrial (Cemina) no Setor Industrial Munir Calixto. A unidade anapolina possui área construída de mais de 51 mil m² e capacidade produtiva de 6.000 mil m²/ano.', NULL),
(369, 'A Fersan Indústria e Comércio Ltda é uma empresa do setor do agronegócio localizada no Distrito Agroindustrial de Anápolis (DAIA), em Goiás. Atua na fabricação e comercialização de insumos para nutrição animal e produtos agropecuários. A empresa está instalada na Via Principal VP 7E do DAIA e atende produtores rurais e distribuidores da região Centro-Oeste.', NULL),
(370, 'A Doce Vida Indústria e Comércio de Produtos Alimentícios Naturais S.A. é uma empresa pioneira no processamento de frutas tropicais em Goiás, fundada em 1992 e sediada no DAIA em Anápolis. Especializada em polpas de frutas congeladas, açaí, sorbets e preparações para a indústria alimentícia e varejo, a empresa foi referência em qualidade no segmento de alimentos naturais. A empresa encontra-se atualmente em processo de recuperação judicial.', NULL),
(371, 'A Embalo Embalagens Lógicas Ltda é uma das pioneiras do Distrito Agroindustrial de Anápolis (DAIA), fundada em 1974, especializada na fabricação de embalagens flexíveis em materiais como PE, PP, BOPP, BOPP metalizado, laminados e PET. Atende principalmente os setores de higiene pessoal e alimentação, com quadro de 201 a 500 funcionários.', NULL),
(372, 'A Centro Oeste Indústria e Comércio de Papéis e Recicláveis é uma empresa anapolina atuante no processamento, compra e venda de materiais recicláveis, com foco em papel e papelão. Inserida no polo industrial de Anápolis, a empresa contribui para a cadeia de reciclagem regional.', NULL),
(373, 'A Remmack Films Ind. e Com. Ltda é uma indústria de embalagens plásticas flexíveis localizada no DAIA, em Anápolis, Goiás. Fundada em 2005, oferece soluções em embalagens com impressão flexográfica de até 8 cores, atendendo indústrias dos setores alimentício, farmacêutico e de higiene.', NULL),
(376, 'A Lunel Eletricidade Ltda é uma fabricante de luminárias e equipamentos de iluminação localizada no Distrito Agroindustrial de Anápolis (DAIA), fundada em 2006. A empresa produz luminárias, arandelas, abajures, refletores e lanternas para uso residencial, comercial e veicular. Atua como microempresa no segmento de iluminação, atendendo o mercado regional e nacional.', NULL),
(377, 'A Excel Construtora e Incorporadora é uma empresa de Anápolis, Goiás, com mais de 25 anos de atuação na construção e incorporação de empreendimentos residenciais, comerciais, industriais e corporativos. Fundada em 1999, a empresa está localizada no Distrito Agroindustrial de Anápolis e atua em projetos de incorporação imobiliária em toda a região. Preza pela qualidade na execução de obras e satisfação dos clientes.', NULL),
(378, 'A Florax e Globo Comércio de Papéis Ltda é uma indústria fabricante de produtos de papel e celulose, especializada em guardanapos de papel, localizada no Distrito Agroindustrial de Anápolis (DAIA). Fundada em 1993, a empresa opera sob a marca Guardanapos Florax e conta com 11 a 50 funcionários. Fabrica produtos à base de celulose destinados ao mercado de higiene e limpeza doméstica.', NULL),
(380, 'A Plastix Ind. Com. e Distribuição de Plástico Ltda é uma empresa fundada em 2001, localizada no Distrito Agroindustrial de Anápolis (DAIA), especializada na transformação e reciclagem de plásticos como polietileno e PEBD. A empresa processa em média 387 toneladas de material por mês, produzindo grânulos, garrafas e embalagens plásticas recicladas. Conta com cerca de 130 funcionários e atende indústrias e o comércio regional.', NULL),
(382, 'A Indicon Ambiental Ltda – EPP é uma empresa especializada em soluções ambientais sediada no Distrito Agroindustrial de Anápolis (DAIA), em Goiás. Atua no tratamento e destinação de resíduos industriais, hospitalares e químicos, prestando serviços para empresas dos estados de Goiás, Mato Grosso, Tocantins, Bahia e Distrito Federal.', NULL),
(385, 'A Sauber é uma empresa anápolitana atuante no segmento de higiene e limpeza, dedicada à fabricação ou distribuição de produtos saneantes e de higiene pessoal. Atende o mercado varejista e institucional da região de Anápolis com produtos de limpeza doméstica e industrial. Anápolis, um dos maiores polos farmacoquímicos e industriais de Goiás, oferece ambiente favorável para empresas do setor.', NULL),
(386, 'A Sotrigo – Sociedade Tritícola de Goiás Ltda é uma empresa alimentícia fundada em 2001 e sediada no Distrito Agroindustrial de Anápolis, Goiás. Atua na moagem de trigo e na fabricação de farinhas, macarrões, snacks, achocolatados e refrigerantes em pó, comercializando seus produtos sob as marcas Sotrigo, Sotrix e Lilita para mercados varejistas e alimentação fora do lar.', NULL),
(387, 'A Gemini Indústria de Insumos Farmacêuticos Ltda é uma empresa do polo farmacêutico de Anápolis, Goiás, especializada na fabricação e distribuição fracionada de insumos farmacêuticos. Fundada em 2009 e sediada no DAIA, a empresa produz cápsulas, comprimidos e suplementos nutricionais, além de importar e distribuir matérias-primas para a indústria farmacêutica nacional. Possui operações tanto em Anápolis quanto em São Paulo.', NULL),
(388, 'O CEPA (Centro de Educação Profissional de Anápolis) é uma instituição de serviços educacionais fundada em 2003, localizada no Distrito Agroindustrial de Anápolis (DAIA). Atua na oferta de educação profissional de nível técnico, formando mão de obra especializada para as indústrias e empresas instaladas na região.', NULL),
(390, 'A Premoldados Melo Ind e Com. Ltda, conhecida pelo nome fantasia Lajeforro, é uma indústria de pré-moldados de concreto com mais de 45 anos de atuação em Anápolis, Goiás. A empresa fabrica lajes, blocos, dormentes, mourões, vigas, postes e outros artefatos de concreto armado para a construção civil.', NULL),
(392, 'A Araguaia S.A. (Adubos Araguaia) é uma das maiores empresas de fertilizantes do Brasil, com sede no Distrito Agroindustrial de Anápolis (DAIA). Possui três fábricas com capacidade de produzir 2,3 milhões de toneladas de fertilizantes por ano e está presente em sete estados brasileiros, com mais de 50 lojas e unidades em Anápolis, Sobradinho (DF) e Catalão.', NULL),
(393, 'A Metalúrgica Souza e Chrispim Ltda é uma empresa metalúrgica localizada em Anápolis (GO), atuante na fabricação de produtos metálicos e serviços de serralheria industrial. Está inserida no polo metalúrgico do Distrito Agroindustrial de Anápolis (DAIA), que concentra diversas empresas do setor e abastece o mercado da construção civil e indústria regional.', NULL),
(394, 'A Gold Pack Indústria e Comércio de Embalagens Ltda é uma fabricante de embalagens personalizadas de papel e papelão, sediada no Distrito Agroindustrial de Anápolis (DAIA), em Goiás. Fundada em 2012, a empresa produz embalagens em diversos formatos para a indústria alimentícia, farmacêutica e demais setores. Utiliza equipamentos modernos para garantir qualidade e aproveitamento máximo das matérias-primas.', NULL),
(397, 'A Transportes Gabardo Ltda é uma unidade do Grupo Gabardo — uma das maiores transportadoras do Brasil — estabelecida no DAIA, em Anápolis, Goiás. Fundada localmente em 2006, realiza transporte rodoviário de cargas gerais em âmbito municipal, intermunicipal e interestadual.', NULL),
(399, 'A B V A Reis Madeiras Ltda, conhecida como Paletes Brasil, é uma fabricante de paletes e embalagens de madeira localizada no DAIA, em Anápolis, Goiás. Fundada em 2008, produz paletes, caixas, engradados e demais embalagens de madeira para uso logístico industrial.', NULL),
(400, 'A Geolab Indústria Farmacêutica S/A é uma das principais farmacêuticas nacionais, fundada em 1999 e sediada no Distrito Agroindustrial de Anápolis (DAIA), um dos maiores polos farmacêuticos do Brasil. A empresa produz medicamentos genéricos, similares, OTCs, fitoterápicos e medicamentos hospitalares, com portfólio superior a 300 SKUs. Mantém presença em 100% das principais redes de farmácias do país, com o varejo representando 70% de sua receita.', NULL),
(401, 'A Trade Construtora e Incorporadora Ltda é uma empresa de construção civil e incorporação imobiliária com sede em Anápolis, Goiás, atuando no DAIA. Participa do desenvolvimento urbano e industrial da região, executando obras e empreendimentos residenciais e comerciais.', NULL),
(407, 'A Pafisa Pré-Moldados Ind e Com Eireli é uma fabricante de artefatos de cimento e pré-moldados para construção civil, localizada no Distrito Agroindustrial de Anápolis (DAIA), em atividade desde 1991. A empresa produz elementos pré-fabricados de concreto utilizados em obras residenciais, comerciais e industriais. Atende construtoras e a cadeia da construção civil na região de Anápolis e entorno.', NULL),
(410, 'A Vigor Alimentos S.A. é uma das maiores empresas de laticínios e alimentos do Brasil, com unidade em Anápolis, Goiás, às margens da BR-060. A empresa opera no processamento e distribuição atacadista de leite e derivados, sendo responsável por marcas consolidadas no mercado nacional de lácteos.', NULL),
(411, 'A Brasil Telecom foi uma das maiores empresas de telecomunicações do Brasil, com presença em Anápolis (GO) por meio de infraestrutura de telefonia fixa e serviços de dados. A empresa emergiu com a privatização do sistema Telebrás e desde 2009 tornou-se subsidiária da Oi.', NULL),
(412, 'A Metalúrgica Esperança Ltda é uma empresa metalúrgica sediada em Anápolis (GO), inserida no Distrito Agroindustrial de Anápolis (DAIA), um dos maiores polos industriais do Centro-Oeste. A empresa atua na fabricação de produtos metálicos, contribuindo para o setor metalúrgico da região que concentra importantes indústrias do estado de Goiás.', NULL),
(413, 'A DBR Indústria Termoplástica Ltda, com nome fantasia Polynner, é uma fabricante de componentes plásticos para calçados localizada no Distrito Agroindustrial de Anápolis (DAIA). Fundada em 2011, a empresa produz solados, palmilhas, saltos e outros componentes de plástico para a indústria calçadista. Está sediada na Via Primária 7-D do DAIA, em Anápolis, Goiás.', NULL),
(414, 'A GSE Automotiva Ltda é uma empresa especializada em engenharia e processos produtivos para o setor automotivo, sediada no Distrito Agroindustrial de Anápolis (DAIA), em Goiás. Fundada em 2011 com investimentos de R$ 10 milhões, a empresa conta com uma fábrica de 3.500 m² com capacidade para soldagem, pintura e montagem de subconjuntos. Atua como fornecedora de montadoras como Hyundai/CAOA, que possui planta em Anápolis.', NULL),
(415, 'A Conpostes Pré-Moldados é uma empresa especializada na fabricação de estruturas de concreto armado pré-moldadas em série, sediada em Anápolis (GO). Produz postes, elementos estruturais e outros componentes de concreto para a construção civil e para obras de infraestrutura na região centro-oeste.', NULL),
(416, 'A Bio Scie Indústria e Comércio Ltda é uma empresa química fundada em 2009 e sediada no Distrito Agroindustrial de Anápolis (DAIA). Atua no comércio atacadista de produtos químicos e petroquímicos, incluindo álcool etílico, soda cáustica, cloro, essências para perfumes e outros insumos para a indústria.', NULL),
(417, 'A Forma Móveis é uma empresa do setor madeireiro e moveleiro sediada em Anápolis, Goiás. Atua na fabricação e comercialização de móveis planejados e seriados para o mercado residencial e corporativo da região Centro-Oeste.', NULL),
(418, 'A Mendes Alimentos Ltda ME é uma empresa do setor alimentício localizada em Anápolis (GO), com atuação na fabricação e comercialização de produtos alimentícios como molhos, temperos e condimentos. Instalada no Distrito Agroindustrial de Anápolis (DAIA), atende supermercados e estabelecimentos comerciais da região Centro-Oeste.', NULL),
(420, 'O Corpo de Bombeiros Militar de Goiás — unidade de Anápolis — é um órgão de segurança pública estadual responsável pelo atendimento a emergências, combate a incêndios, resgate de vítimas e ações de defesa civil no município e região. Integra a estrutura da Secretaria de Segurança Pública do Estado de Goiás.', NULL),
(423, 'Melquíades Múscua Filho ME é uma microempresa industrial sediada em Anápolis, Goiás, atuando na fabricação artesanal ou em pequena escala de produtos manufaturados. Opera no polo industrial anápolitano, um dos mais diversificados de Goiás, aproveitando a infraestrutura disponível na cidade. Atende clientes locais e regionais com produtos de sua linha de produção.', NULL),
(425, 'A Jetlog Transportes e Logística Ltda é uma empresa anapolina fundada em 2012, especializada em transporte e organização logística de cargas. Está localizada no Distrito Agroindustrial de Anápolis (DAIA) e atua no escoamento de mercadorias aproveitando a infraestrutura multimodal da cidade. A empresa integra o ecossistema logístico regional que serve indústrias do polo de Anápolis e do Centro-Oeste.', NULL),
(426, 'A Jetlog Logística Ltda é uma empresa de organização e operação logística de cargas com sede em Anápolis (GO), localizada no Distrito Agroindustrial da cidade. Opera no segmento de logística de transporte de mercadorias, aproveitando a posição estratégica de Anápolis como hub logístico do Centro-Oeste brasileiro, com acesso a rodovias, ferrovia e aeroporto de cargas.', NULL),
(427, 'A Pontes Ind. Metalúrgica Ltda, comercialmente conhecida como Pontes Construtivos Metálicos, é uma empresa fundada em 2001 e localizada no Distrito Agroindustrial de Anápolis (DAIA). Especializada na fabricação de estruturas metálicas, coberturas metálicas, galpões, mezaninos e construções industriais em aço, a empresa conta com equipe técnica especializada e entre 51 e 200 funcionários. Atende construtoras, indústrias e empresas de toda a região Centro-Oeste.', NULL),
(429, 'A Carta Goiás Indústria e Comércio de Papéis S.A. é uma unidade do grupo Carta Fabril, um dos maiores complexos papeleiros do Centro-Oeste brasileiro, localizada no Distrito Agroindustrial de Anápolis (DAIA). A empresa atua na fabricação de papel, papelão e embalagens de papelão ondulado para uso comercial e industrial.', NULL),
(431, 'A Sabaré Químicos e Ingredientes S.A. é uma empresa do Grupo Sabará, líder latino-americano no fornecimento de produtos para tratamento de água e saneamento industrial. Fundada em 2002, a unidade de Anápolis (DAIA) produz e distribui cloro, hipoclorito e outros produtos químicos para desinfecção e tratamento de água em processos industriais em todo o Brasil.', NULL),
(432, 'A Champion Farmoquímico Ltda é uma empresa com mais de 30 anos de atuação, sediada no Distrito Agroindustrial de Anápolis (DAIA), que atua na fabricação de produtos farmoquímicos para uso humano e veterinário. Seus produtos estão presentes em mais de dez países, com contribuições a campanhas de saúde pública da Organização Mundial da Saúde.', NULL),
(434, 'A Usina Termelétrica de Anápolis Ltda, também conhecida como UTE-DAIA, é uma usina geradora de energia elétrica a diesel localizada no Distrito Agroindustrial de Anápolis (DAIA), em Goiás. Com capacidade instalada de 44,3 MW distribuídos em 33 conjuntos de motogeradores, iniciou operações em 2003 para suprir a demanda energética do polo industrial.', NULL),
(435, 'A Ideal Farma Indústria e Comércio de Produtos Farmacêuticos Ltda (Idealfarma) é uma empresa 100% nacional fundada há mais de 20 anos em Anápolis, Goiás, especializada na produção de insumos farmacêuticos e nutracêuticos para farmácias de manipulação. A empresa se destaca como uma das maiores produtoras de cápsulas de gelatina mole (Softgel) do Brasil. Opera no polo farmacêutico do DAIA e possui também unidade administrativa em São Paulo.', NULL),
(436, 'A Moldar Engenharia Ltda é uma empresa do setor de construção civil localizada em Anápolis (GO). Atua em projetos e obras de engenharia, atendendo demandas do mercado imobiliário e industrial da cidade, que é um dos maiores polos de desenvolvimento do interior do Centro-Oeste. Anápolis concentra diversas construtoras que atendem tanto o setor industrial quanto o residencial e comercial.', NULL),
(438, 'A Gerbrás Ingredientes é uma indústria alimentícia fundada em 1981 e sediada no Distrito Agroindustrial de Anápolis (DAIA), atuante na fabricação de ingredientes e produtos alimentícios. Com mais de 40 anos de mercado, a empresa fornece insumos e ingredientes para a indústria de alimentos da região Centro-Oeste e demais regiões do Brasil. Está registrada na Rua R6 do DAIA em Anápolis, Goiás.', NULL),
(440, 'A Competec Máquinas Indústria e Comércio Ltda é uma empresa de Anápolis, Goiás, especializada na fabricação e manutenção de máquinas e equipamentos industriais. A empresa é referência no Centro-Oeste em metrologia industrial, sendo o primeiro laboratório privado da região acreditado pelo Inmetro em quatro grupos de serviços. Atua em automação industrial, usinagem de precisão, metalurgia e manutenção de equipamentos.', NULL),
(441, 'A Colatex Indústria e Comércio Ltda é uma empresa sediada no Distrito Agroindustrial de Anápolis (DAIA), em Goiás, atuante na fabricação de tintas, vernizes, esmaltes e lacas. A empresa foi fundada em 1991 e teve suas operações adquiridas pela Saint-Gobain do Brasil. Opera no segmento de revestimentos industriais e para construção civil.', NULL),
(442, 'A JRA Logística Ltda é uma empresa anapolina que presta serviços de transporte rodoviário de cargas secas, cargas completas e cargas especiais em todo o Brasil. Com frota própria, tecnologia de rastreamento e mais de 600 motoristas habilitados, a empresa oferece soluções logísticas customizadas para os setores da construção civil, vidros, usinagem e indústria em geral.', NULL),
(443, 'A Softech Brasil S/A é uma empresa especializada na fabricação de cápsulas gelatinosas moles (softgel), localizada no DAIA, em Anápolis, Goiás. Com atuação desde 2000, produz cápsulas para suplementos nutricionais como colágeno e ômega-3, atendendo marcas que desejam terceirizar a produção ou adquirir cápsulas a granel.', NULL),
(444, 'A Copalimpa Indústria Têxtil Ltda é uma fabricante de artigos têxteis para uso doméstico, especializada em panos de chão, localizada no Distrito Agroindustrial de Anápolis, Goiás. Fundada em 2003, a empresa atua no segmento de confecção e produção de artigos de limpeza têxtil. Está sediada na Rua VI L1 do DAIA e possui registro ativo junto à Receita Federal.', NULL),
(447, 'A Galgane Construtora Ltda é uma empresa de construção civil atuante em Aparecida de Goiânia, Goiás, município que integra a região metropolitana de Goiânia. A empresa atua no desenvolvimento e execução de obras de construção e incorporação imobiliária na região. Aparecida de Goiânia é um dos principais polos construtivos de Goiás, com intensa atividade no setor da construção civil.', NULL),
(449, 'A Transhenry Transportes Ltda é uma empresa de logística e transporte de cargas com sede no DAIA, em Anápolis, Goiás, atuando desde 2004. Certificada pela ANVISA, opera no transporte intermunicipal, interestadual e internacional, com filiais em diversos estados brasileiros. Especializada em distribuição para indústrias do polo farmacêutico e alimentício de Anápolis.', NULL),
(451, 'A Delfus Pré-Moldados Indústria e Comércio Eireli, operando sob o nome fantasia Lajes Vibracom, é uma fabricante de artefatos de cimento pré-moldados para construção civil, com foco em lajes e elementos estruturais. Fundada em 2003, a empresa está localizada no Distrito Agroindustrial de Aparecida de Goiânia (DAIAG). Atende o mercado da construção civil com produtos de concreto para uso em obras residenciais e comerciais.', NULL),
(452, 'Alexandre Antônio de Souza é um produtor rural ou prestador de serviços do agronegócio com atuação em Mineiros, Goiás. Dedica-se a atividades agropecuárias típicas do cerrado goiano, como cultivo de grãos ou pecuária de corte e leite. Mineiros é reconhecida pela forte vocação agroindustrial, especialmente na produção de soja e milho.', NULL),
(456, 'O Restaurante e Lanchonete DAIAG é um estabelecimento de alimentação coletiva sediado em Aparecida de Goiânia, Goiás, prestando serviços de refeições e lanches para trabalhadores do Distrito Agroindustrial de Aparecida de Goiânia (DAIAG). Atende diariamente funcionários das indústrias e empresas instaladas no distrito industrial, sendo referência em alimentação no polo. Oferece refeições completas e opções rápidas de lanchonete para o público trabalhador da região.', NULL),
(461, 'A Metalúrgica Amaral Ltda é uma indústria de máquinas e equipamentos para beneficiamento de vidros localizada no Distrito Agroindustrial de Aparecida de Goiânia (DAIAG), fundada em 2008. Com proprietários com mais de 30 anos de experiência no setor de vidros, a empresa fabrica furadeiras industriais, equipamentos para tempera e acessórios específicos para vidraçarias. Seus produtos atendem o mercado regional e nacional.', NULL),
(462, 'A Five Elements é uma empresa industrial localizada em Aparecida de Goiânia, Goiás, atuante no Distrito Agroindustrial de Aparecida de Goiânia (DAIAG). Opera no segmento de fabricação industrial, atendendo o mercado regional com produtos manufaturados. A empresa integra o polo industrial de Aparecida de Goiânia, que conta com mais de 2.200 indústrias e é o terceiro município mais industrializado de Goiás.', NULL),
(463, 'A Protege Indústria e Comércio de Equipamentos de Segurança Ltda é uma fabricante e distribuidora de Equipamentos de Proteção Individual (EPIs), com sede no Distrito Agroindustrial de Aparecida de Goiânia (DAIAG). Fundada em 2004, atua há mais de 20 anos na fabricação de equipamentos e acessórios para segurança pessoal e profissional.', NULL),
(464, 'A Cria Pecuária Técnica Ltda é uma empresa do agronegócio sediada em Aparecida de Goiânia, Goiás. Atua com foco em pecuária técnica, oferecendo serviços especializados de manejo, consultoria e comercialização de animais e insumos para produtores rurais da região.', NULL),
(465, 'A Enol Empresa Nacional de Obras Ltda é uma construtora sediada no Distrito Agroindustrial de Aparecida de Goiânia (DAIAG), atuante na construção de edifícios residenciais, comerciais e industriais. Fundada em 1989, a empresa opera também com a fabricação de pré-moldados de concreto, sob o nome fantasia Mold Premoldados. Atende demandas de construção civil na região metropolitana de Goiânia.', NULL),
(469, 'A Nativa Cosméticos Ltda é uma empresa goiana sediada em Mineiros dedicada à fabricação e comercialização de produtos cosméticos. Atua no desenvolvimento de linhas de beleza e cuidados pessoais voltadas ao mercado regional e nacional. Sua produção abrange itens para cuidados com cabelos, pele e higiene pessoal.', NULL),
(471, 'A Prefeitura Municipal de Mineiros é o órgão do Poder Executivo responsável pela administração pública do município de Mineiros, no sudoeste de Goiás. Compete ao município a gestão de serviços essenciais como saúde, educação, infraestrutura urbana e assistência social. Mineiros é um importante polo do agronegócio e conta com dois distritos agroindustriais que abrigam centenas de empresas.', NULL),
(477, 'A Perdigão, hoje parte do Grupo BRF, implantou em Mineiros (GO) o Complexo Agroindustrial inaugurado em março de 2007, com investimento total de R$ 510 milhões. A unidade, composta por dois abatedouros e um incubatório, tem capacidade para produzir 81 mil toneladas anuais de cortes de frango pesado, sendo aproximadamente 80% da produção destinada ao mercado externo.', NULL),
(478, 'Jardel Jacoby é um produtor rural e empresário do agronegócio atuante no município de Mineiros, no sudoeste de Goiás. A região de Mineiros é reconhecida pela produção em larga escala de soja, milho e pecuária, inserida no Cerrado goiano.', NULL),
(480, 'Luis Antonio Golveia é um profissional ou empresário individual com atividades registradas no município de Mineiros, Goiás. Atua em atividades econômicas do município, que é um polo agroindustrial no sudoeste do estado.', NULL),
(488, 'A Montana Auto Recuperadora Ind e Com Ltda é uma empresa sediada em Mineiros (GO) que atua no setor moveleiro e de recuperação de produtos industriais. A empresa está instalada no distrito agroindustrial local, que concentra empresas de manufatura e transformação do sudoeste goiano.', NULL),
(491, 'A Passinato Cereais Ltda é uma empresa do agronegócio sediada no Distrito Agroindustrial de Mineiros (DAIM), atuante no armazenamento e comercialização de grãos. Fundada em 2020, a empresa opera no segmento de armazéns gerais com emissão de warrant, apoiando a cadeia produtiva de cereais da região sudoeste de Goiás.', NULL),
(505, 'Empresa atuante na área de administração e gestão, com sede em Mineiros, Goiás. Presta serviços de suporte administrativo, controle de processos e apoio operacional a outras organizações da região. Atua como estrutura de gestão centralizada para operações locais.', NULL),
(514, 'Oseas Rodrigues é um profissional ou microempreendedor individual que atua no ramo metalúrgico no município de Orizona, Goiás. No setor metalúrgico, profissionais autônomos realizam atividades como soldagem, fabricação de estruturas metálicas, grades, portões e equipamentos agrícolas.', NULL),
(518, 'A M S Industria e Comércio Madeiras Ltda é uma empresa do setor madeireiro localizada em Aparecida de Goiânia (GO). Atua na industrialização e comercialização de produtos de madeira, abastecendo o mercado regional da construção civil, moveleiro e afins. Opera no DAIAG, aproveitando a infraestrutura do polo industrial da cidade.', NULL),
(521, 'A GDG Logística e Transportes Ltda é uma empresa do setor de logística e transporte rodoviário de cargas, sediada em Aparecida de Goiânia, Goiás. Atua no transporte intermunicipal, interestadual e internacional de cargas, exceto produtos perigosos e mudanças. A empresa está localizada na região metropolitana de Goiânia, área estratégica para operações logísticas do Centro-Oeste brasileiro.', NULL),
(523, 'A CDA Alimentos S.A. foi fundada em 1991 como Cereais Araguaia e ao longo dos anos se tornou uma das maiores empresas do setor de alimentos no país. A empresa adquiriu a marca Tio Jorge em 2006 e diversificou suas operações, atuando também na comercialização de milho para indústrias brasileiras e para exportação.', NULL),
(526, 'A Rede Ferroviária Federal S.A. (RFFSA) foi uma empresa estatal brasileira criada em 1957 para administrar e modernizar as ferrovias da União, com operações em Anápolis ligadas ao escoamento de produção do DAIA para portos do Sudeste. A malha ferroviária de Anápolis tornou-se concessão da Ferrovia Centro-Atlântica após a privatização da RFFSA entre 1996 e 1998. A empresa foi extinta em 2007.', NULL),
(527, 'A JL Ind e Com de Máquinas Industriais Ltda é uma empresa fabricante e comercializadora de máquinas industriais sediada em Aparecida de Goiânia, Goiás. Produz e distribui equipamentos industriais para diferentes segmentos produtivos da grande Goiânia e interior do estado. Oferece soluções de automação e maquinário para aumentar a produtividade de indústrias clientes.', NULL),
(529, 'A Montherm Indústria Comércio e Serviços Ltda é uma empresa especializada em isolamento térmico e acústico, sediada em Aparecida de Goiânia, Goiás. Fabrica e instala sistemas de isolamento para tubulações, equipamentos industriais, câmaras frias e edificações, atendendo indústrias e o setor de construção da região. Oferece também serviços de impermeabilização e proteção contra variações térmicas.', NULL),
(530, 'A Kelldrin Industrial Ltda é uma indústria familiar fundada em 2002, com sede em Aparecida de Goiânia (GO), atuante nos segmentos de saúde animal, saúde ambiental e saúde humana. A empresa oferece soluções em higiene, limpeza e controle de pragas, atendendo supermercados, empresas agrícolas, farmácias e construção civil. Com distribuição nacional, possui também um centro de distribuição em Recife para ampliar seu alcance.', NULL),
(531, 'A Fatri Indústria e Comércio Ltda é uma fabricante de argamassas, artefatos de cimento e produtos para construção civil, localizada no Distrito Agroindustrial de Aparecida de Goiânia (DAIAG). Fundada em 1988 e atuante por mais de 34 anos no setor, a empresa opera sob a marca Fatri Argamassas. Comercializa produtos como argamassas industrializadas, impermeabilizantes e aditivos para construção.', NULL),
(532, 'A Limpis Industrial Ltda é uma fabricante de produtos de limpeza e polimento com sede no Distrito Agroindustrial de Aparecida de Goiânia (GO), em atividade desde 1994. A empresa produz artigos para higiene e conservação de superfícies, contando com uma equipe de 21 a 50 funcionários. Seu CNPJ ativo confirma operação contínua no setor de higiene e limpeza da região metropolitana de Goiânia.', NULL),
(533, 'A Leviale Ind Cosmética Ltda é uma indústria de cosméticos sediada em Aparecida de Goiânia, Goiás, dedicada à formulação e fabricação de produtos de beleza e higiene pessoal. Produz cosméticos como shampoos, condicionadores, cremes e produtos para cuidados corporais para distribuição no mercado nacional. Integra o segmento industrial cosmético goiano, que atende tanto marcas próprias quanto terceirização para outras marcas.', NULL),
(535, 'O Posto Tabocão em Aparecida de Goiânia é uma unidade do grupo Tabocão, voltada à revenda varejista de combustíveis para veículos automotores. Localizado no Distrito Agroindustrial de Aparecida de Goiânia (DAIAG), atende motoristas e empresas da região metropolitana de Goiânia.', NULL),
(536, 'A Metalúrgica Cavagi Ltda é uma empresa fundada em 1992 localizada no Distrito Agroindustrial de Aparecida de Goiânia (DAIAG), especializada na fabricação de reservatórios metálicos, tanques e caldeiras. Atende o mercado de armazenamento de água e combustíveis, produzindo reservatórios do tipo taça e cilíndrico para uso industrial e residencial. A empresa é um dos destaques do polo metalúrgico de Aparecida de Goiânia.', NULL),
(537, 'A Bio Brasil Biotecnologia Ltda é uma empresa de biotecnologia localizada no DAIA, em Anápolis, Goiás, especializada no desenvolvimento e produção de produtos para a saúde, incluindo sanitizantes de alto desempenho, biomateriais odontológicos e instrumentais médico-hospitalares.', NULL),
(538, 'A Rejumassa Indústria, Comércio e Transportes de Rejuntes Ltda é uma fabricante de materiais para revestimento e acabamento da construção civil, sediada no Distrito Agroindustrial de Aparecida de Goiânia (DAIAG). Fundada em 2011, produz rejuntes para porcelanato, argamassas, gesso rápido e cimento branco estrutural.', NULL),
(540, 'A Cavaco''s Combustíveis de Biomassa Indústria e Comércio Ltda é uma empresa fundada em 2003, localizada no Distrito Agroindustrial de Aparecida de Goiânia (GO). Produz combustível de biomassa (cavacos de madeira) para queima em fornos e caldeiras industriais, oferecendo também serviços de gestão e destinação final de resíduos de madeira como alternativa renovável aos combustíveis fósseis.', NULL),
(541, 'A Construtora e Indústria Cagesul Ltda é uma empresa metalúrgica fundada em 1990 e sediada em Aparecida de Goiânia (GO), especializada na fabricação de tanques, reservatórios metálicos e caldeiras para aquecimento. Atende demandas industriais da Grande Goiânia e de outros municípios do estado.', NULL),
(543, 'A Indústria e Revestimento Criscola Ltda é uma empresa atuante no setor de construção civil em Aparecida de Goiânia (GO), com foco na fabricação e comercialização de revestimentos para ambientes residenciais e comerciais. O município é um dos maiores polos industriais do estado de Goiás, com tradição em empresas de materiais de construção e acabamento.', NULL),
(545, 'A Nikon Ind. de Tintas Ltda é uma indústria fabricante de tintas, vernizes e produtos correlatos sediada em Aparecida de Goiânia, Goiás. Produz tintas imobiliárias, esmaltes, primers e complementos para o setor de construção civil e reforma. Distribui seus produtos para lojas de material de construção e distribuidores da grande Goiânia e interior do estado.', NULL),
(547, 'A Carneiro e Canedo Administração e Participação é uma holding sediada em Aparecida de Goiânia, Goiás, voltada para a gestão de participações societárias e investimentos em empresas do grupo. Centraliza decisões estratégicas e financeiras de negócios sob seu controle na região metropolitana de Goiânia. Atua como estrutura de governança corporativa para o portfólio de empresas dos sócios.', NULL),
(552, 'A Copel Indústria e Comércio de Recicláveis Ltda é uma das empresas pioneiras em reciclagem de papel, papelão e plásticos em Goiás, com mais de 40 anos de mercado. Opera três centros de processamento totalizando 100 mil metros quadrados, nos municípios de Goiânia, Anápolis e Aparecida de Goiânia. Conta com prensas verticais e horizontais, fragmentadores, moinhos e frota própria para atendimento em todo o Estado de Goiás.', NULL),
(554, 'A M. Fortes Artefatos de Cimento e Materiais de Construção é uma empresa de Aparecida de Goiânia (GO) especializada na fabricação de artefatos de cimento, como blocos, lajes, meio-fio e outros pré-moldados usados na construção civil. A empresa abastece obras residenciais, comerciais e de infraestrutura na Grande Goiânia e municípios vizinhos.', NULL),
(555, 'A Vasap Indústria, Comércio e Distribuição Ltda, atuante sob o nome fantasia Vasap Design, é uma fabricante de artefatos plásticos localizada no Distrito Agroindustrial de Aparecida de Goiânia (DAIAG). Fundada em 2004, transforma plásticos que seriam descartados na natureza em vasos, acessórios e peças de decoração, utilizando exclusivamente plástico 100% reciclado.', NULL),
(556, 'A Distribuidora Brasileira de Asfalto Ltda (DISBRAL) é uma das maiores empresas do setor de asfalto do Brasil, fundada em 1991 e sediada no Distrito Agroindustrial de Aparecida de Goiânia. Atua na produção e distribuição de emulsões asfálticas, misturas a frio e quente (CBUQ), revenda de asfalto e aplicação de microrevestimentos e slurry seal. Sua área de atuação abrange principalmente as regiões Centro-Oeste e Sudeste do Brasil.', NULL),
(558, 'A Renovar Reciclagem de Materiais Ltda é uma empresa sediada em Aparecida de Goiânia, Goiás, dedicada à coleta e beneficiamento de materiais recicláveis. Opera na triagem e processamento de sucatas, plásticos e outros resíduos sólidos recuperáveis para reintrodução na cadeia produtiva. Contribui para a gestão ambiental responsável de resíduos na região metropolitana de Goiânia.', NULL),
(560, 'A Orizona Produtos Agropecuários Ltda, também conhecida pela marca Mercecampo, é uma empresa do agronegócio fundada em 1997 e sediada em Orizona (GO). Atua no beneficiamento e fabricação de produtos de origem vegetal, além de comercializar insumos e produtos agropecuários para produtores da região.', NULL),
(561, 'A Alves Construção Ltda é uma empresa do setor de construção civil sediada em Aparecida de Goiânia, na região metropolitana de Goiânia. Atua na execução de obras civis, edificações residenciais e comerciais, e serviços de construção em geral. A empresa aproveita a expansão urbana acelerada da região para oferecer soluções construtivas à crescente demanda local.', NULL),
(565, 'A Prefeitura Municipal de Orizona é o órgão do Poder Executivo responsável pela administração do município de Orizona, localizado no sudeste do estado de Goiás. Cabe ao poder municipal gerir serviços públicos de saúde, educação, infraestrutura e assistência social. Orizona tem sua economia baseada na agropecuária e conta com um pequeno parque agroindustrial.', NULL),
(570, 'A Mult Pedras D & D Ltda é uma empresa de Catalão (GO) que atua no setor de construção civil com foco no comércio e beneficiamento de pedras naturais e materiais de revestimento. Catalão é um importante polo industrial e minerador do sudeste goiano, o que favorece o desenvolvimento de empresas ligadas à extração e transformação de rochas ornamentais.', NULL),
(574, 'A Precisão Serviços Ltda é uma empresa de Catalão (GO) que presta serviços no setor de máquinas e equipamentos industriais. Catalão é reconhecida como polo automotivo e minerador de Goiás, com forte demanda por empresas de manutenção, calibração e operação de equipamentos.', NULL),
(576, 'O Pastifício Sta Clara Ltda é uma fabricante de massas alimentícias artesanais localizada em Aparecida de Goiânia (GO), em atividade desde 2001. A empresa produz massas frescas e secas como macarrão, lasanha, nhoque e outros produtos à base de trigo. Atende o mercado local e da região metropolitana de Goiânia, com foco em qualidade artesanal e variedade no portfólio.', NULL),
(579, 'José Lucas Ribeiro é um produtor rural ou empresário individual do agronegócio com atuação no município de Orizona, Goiás. A região de Orizona é marcada pela produção agrícola e pela pecuária extensiva, integrando a cadeia produtiva do Centro-Oeste brasileiro.', NULL),
(585, 'A Mosaic Fertilizantes do Brasil é uma das maiores empresas do setor de fertilizantes no país, com operações estratégicas de mineração de fosfato em Catalão (GO) desde 1982. O Complexo Mineroquímico de Catalão é responsável por cerca de 54% da produção de fosfatados do Centro-Oeste, representando mais de 1.800 empregos diretos e indiretos no município. A empresa é subsidiária da The Mosaic Company, gigante americana entre os maiores produtores mundiais de fertilizantes.', NULL),
(596, 'A Mercecampo Medicamentos Veterinários Eireli é uma empresa do agronegócio sediada em Orizona (GO), especializada na distribuição e comercialização de medicamentos e produtos veterinários para uso animal. A empresa atende produtores rurais e revendas agropecuárias do município e municípios vizinhos.', NULL),
(600, 'A Goiasflora Empreendimentos Florestais é uma empresa atuante no setor madereiro com sede em Catalão (GO), dedicada a empreendimentos florestais como plantio, manejo e comercialização de madeira. O setor florestal no Cerrado goiano vem crescendo com o avanço das plantações de eucalipto e pinus voltadas à indústria e energia.', NULL),
(603, 'A Metalúrgica Concept Ltda é uma empresa sediada em Catalão (GO) que atua na fabricação de estruturas e componentes metálicos voltados à construção civil e à indústria em geral. Catalão possui um consolidado parque industrial metalúrgico, favorecido pela presença de mineradoras e montadoras automotivas na região.', NULL),
(608, 'MJ Nunes Prequete é uma empresa individual ou microempresa do setor metalúrgico com sede em Orizona (GO). Atua na fabricação ou reforma de peças, estruturas metálicas e equipamentos de pequeno porte para o mercado local, atendendo demandas da construção civil e do setor agropecuário regional.', NULL),
(611, 'A Motora Indústria e Comércio Ltda é uma empresa do setor automobilístico sediada no Distrito Minero Industrial de Catalão (GO), especializada na fabricação de cabines, carrocerias e implementos para veículos. Catalão é o principal polo automotivo do estado de Goiás, abrigando montadoras e fornecedores da cadeia automotiva.', NULL),
(618, 'O Corpo de Bombeiros Militar do Estado de Goiás, com unidade em Catalão, é a instituição pública estadual responsável pela prevenção e combate a incêndios, salvamento, resgate e defesa civil no município e na região. A unidade de Catalão atende um dos municípios mais industrializados do interior goiano.', NULL),
(632, 'Joaquim Evangelista ME é uma microempresa atuante no setor de construção civil em Catalão (GO), prestando serviços como execução de obras, reformas e serviços gerais de edificação. A empresa atende demandas residenciais e comerciais no município, que apresenta crescimento urbano impulsionado pela indústria mineral e automotiva.', NULL),
(648, 'Thiago Silva Cortopassi Eireli é uma empresa individual atuante no setor de construção civil em Catalão (GO). Presta serviços de obras civis, reformas ou fornecimento de materiais e mão de obra especializada para projetos residenciais e comerciais.', NULL),
(651, 'A Oliveira e Magalhães Materiais para Construção Ltda é uma empresa varejista e atacadista de materiais de construção civil sediada em Catalão (GO). Comercializa uma linha completa de insumos como cimento, areia, blocos, ferragens e acabamentos para obras residenciais e comerciais.', NULL),
(654, 'A ADN 22 Ind. de Couro Ltda ME é uma microempresa industrial sediada em Catalão, Goiás, especializada no beneficiamento e industrialização de couro. Atua no processamento de peles bovinas para fornecimento de matéria-prima ao setor calçadista, moveleiro e de artefatos de couro. Sua localização em Catalão favorece o acesso a insumos do agronegócio regional.', NULL),
(661, 'A Acofergo Tubos e Perfilados Ltda é uma empresa metalúrgica sediada em Goiatuba, Goiás, especializada na fabricação de tubos, perfis e laminados metálicos. Fornece insumos metálicos para a construção civil, agricultura e indústria em geral na região sul goiana. Atua também na distribuição de aço e materiais siderúrgicos para o mercado regional.', NULL),
(665, 'A MI Serviços Confecção e Comércio de Pré Moldados Ltda é uma empresa de Catalão (GO) que fabrica e comercializa elementos pré-moldados de concreto, como postes, mourões, blocos e peças estruturais para a construção civil. O uso de pré-moldados é amplamente difundido em obras de infraestrutura rural e urbana no Centro-Oeste.', NULL),
(666, 'A CTBC – Companhia de Telecomunicações do Brasil Central, hoje parte do Grupo Algar, é uma operadora de telecomunicações fundada em 1954 com atuação em Goiás, Minas Gerais e outros estados. Em Goiatuba e região, a empresa oferece serviços de telefonia fixa, internet banda larga e soluções corporativas de conectividade.', NULL),
(671, 'A Oxynobre Gases Industriais Ltda é uma empresa goiana fundada em 2012, especializada na produção e distribuição de gases industriais e medicinais como oxigênio, nitrogênio, argônio e dióxido de carbono em alta pureza. Com sede no Distrito Agroindustrial de Itumbiara e atuação na região de Goiatuba, a empresa atende clientes nos estados de Goiás, Tocantins, Mato Grosso e no Triângulo Mineiro.', NULL),
(679, 'A Nutrisal Indústria e Comércio Suplementos para Alimentação Animal Ltda, parte do Grupo Nutrisal, é uma empresa fundada em 1990 e sediada no Distrito Agroindustrial de Rio Verde (DARV I), em Goiás. Atua na fabricação de rações balanceadas, sal mineral, suplementos vitamínicos e premixes para bovinos, suínos, aves e outros animais. Rio Verde é considerada a capital do agronegócio goiano, e a Nutrisal é um dos principais fornecedores de suplementação animal da região Centro-Oeste.', NULL),
(688, 'A Controltech Mangueiras Ltda é uma empresa de Rio Verde (GO) que atua no fornecimento de mangueiras industriais, conexões e sistemas hidráulicos aplicados à construção civil, ao agronegócio e à indústria em geral. Rio Verde é o maior polo do agronegócio goiano, gerando intensa demanda por fornecedores de peças e componentes para máquinas agrícolas e equipamentos industriais.', NULL),
(689, 'Gutenberg Rodrigues Barros Junior é um profissional ou empresário individual que atua no setor moveleiro no município de Rio Verde (GO). O setor moveleiro de Rio Verde abriga diversas empresas de fabricação de móveis planejados e seriados, atendendo a demanda crescente gerada pelo desenvolvimento econômico do município.', NULL),
(691, 'A Grandis Indústria e Comércio Ltda é uma empresa madereira fundada em 2003 e sediada no Distrito Agroindustrial de Rio Verde (DARV I), especializada na fabricação de embalagens e artefatos de madeira, como paletes e caixarias. A empresa também realiza atividades de serraria e beneficiamento de madeira bruta, atendendo indústrias e empresas do agronegócio da região.', NULL),
(692, 'A Finart Indústria e Comércio de Móveis Ltda é uma empresa fabricante de móveis sediada em Senador Canedo (GO), município que integra a região metropolitana de Goiânia e abriga um expressivo polo moveleiro. A empresa produz móveis residenciais e comerciais, atendendo clientes na Grande Goiânia e em outras regiões do estado.', NULL),
(693, 'ER Loures Loures Eireli é uma empresa individual atuante no setor moveleiro em Senador Canedo (GO), com foco na fabricação ou comercialização de móveis para o mercado local e regional. Senador Canedo concentra diversas indústrias do polo moveleiro da Grande Goiânia.', NULL),
(694, 'A Indústria e Comércio Bioplástico Ltda é uma empresa de Rio Verde (GO) atuante no setor de materiais plásticos, dedicada à fabricação, transformação ou reciclagem de produtos plásticos para uso industrial ou doméstico. Rio Verde é um polo industrial em crescimento no sudoeste goiano, com demanda por embalagens e componentes plásticos gerada pelo agronegócio e pela indústria alimentícia da região.', NULL),
(696, 'Joenia Alves Pereira Santos – ST Mobile é uma microempresa com atividades registradas no setor de construção civil em Senador Canedo (GO). Atua possivelmente com serviços de acabamento, reformas ou pequenas obras no município, que integra a Grande Goiânia e apresenta intenso crescimento urbano.', NULL),
(697, 'Edivaldo Mendes Pereira é um profissional ou microempreendedor individual atuante no setor de construção civil em Rio Verde (GO). Na maior cidade do sudoeste goiano, a construção civil acompanha o crescimento acelerado da economia local impulsionada pelo agronegócio.', NULL),
(699, 'A Central de Serviços é uma empresa prestadora de serviços gerais sediada em Senador Canedo, Goiás. Atua no suporte operacional e logístico a empresas do Distrito Industrial local, oferecendo soluções terceirizadas nas áreas de manutenção, limpeza e conservação. Sua localização em Senador Canedo permite atendimento ágil às indústrias instaladas no entorno da capital.', NULL),
(701, 'A Post Portas Indústria de Móveis Ltda é uma empresa fabricante de portas e móveis sediada em Senador Canedo (GO), integrante do polo moveleiro da Grande Goiânia. A empresa produz portas de madeira e derivados para o mercado residencial e comercial, atendendo construtoras, revendas e consumidores finais.', NULL),
(704, 'A IMOL – Indústria de Móveis Oliveira é uma empresa fabricante de móveis sediada em Senador Canedo (GO), com foco na produção de móveis em madeira e seus derivados para o mercado residencial e corporativo. Integra o polo moveleiro do Distrito Agroindustrial de Senador Canedo, que concentra dezenas de fabricantes e fornecedores do setor.', NULL),
(706, 'O Centro Sul Ind. e Com. de Portas e Janelas é uma indústria fabricante de esquadrias, portas e janelas sediada em Senador Canedo, Goiás. Produz componentes para construção civil em madeira, alumínio ou PVC, atendendo construtoras e o varejo especializado da região metropolitana de Goiânia. Integra a cadeia produtiva da construção civil do entorno da capital.', NULL),
(708, 'A Jota PR Indústria e Comércio de Móveis é uma empresa do setor moveleiro com sede em Senador Canedo (GO), dedicada à fabricação e comercialização de móveis para o mercado local e regional. O polo moveleiro de Senador Canedo reúne empresas que empregam técnicas de marcenaria industrial e atendem consumidores diretos e lojas de decoração.', NULL),
(709, 'A F A E Indústria e Comércio Ltda é uma empresa do setor metalúrgico sediada em Senador Canedo (GO), atuando na fabricação de componentes, estruturas metálicas ou peças usinadas para clientes industriais da Grande Goiânia. O município conta com um distrito agroindustrial ativo, onde empresas metalúrgicas atendem demandas da construção civil e da indústria.', NULL),
(711, 'A Essencial Móveis Planejados Ltda é uma empresa de Rio Verde (GO) especializada na fabricação e comercialização de móveis planejados para ambientes residenciais e comerciais. Acompanha o crescimento econômico de Rio Verde, cidade que é o maior polo do agronegócio goiano e possui uma classe média em expansão com alta demanda por móveis sob medida.', NULL),
(712, 'A Stefani Fertilizantes Especiais Eireli é uma empresa fundada em 1991 e sediada no Distrito Agroindustrial de Senador Canedo (GO), especializada na fabricação de fertilizantes especiais e adubos para uso agrícola. Com mais de três décadas de atuação, a empresa atende produtores rurais e distribuidoras de insumos agrícolas em Goiás e estados vizinhos.', NULL),
(717, 'A Zignut Ferro e Aço Ltda é uma empresa metalúrgica fundada em 1984 com indústria instalada no Distrito Agroindustrial de Senador Canedo (GO). Especializada na fabricação de perfis dobrados, tubos, telhas galvanizadas e galvalume, chapas e vigas estruturais, a empresa oferece ainda serviços de corte e dobra para clientes dos setores metalúrgico e de construção civil.', NULL),
(718, 'A Prefeitura Municipal de Rio Verde é o órgão do Poder Executivo responsável pela administração do maior município do sudoeste de Goiás, considerado a capital do agronegócio goiano. O município se destaca pela produção de grãos, proteína animal e por abrigar grandes empresas processadoras como BRF e Comigo. A gestão municipal coordena políticas públicas para uma população de mais de 250 mil habitantes.', NULL),
(719, 'A Dilutec Indústria e Comércio de Produtos Químicos é uma empresa 100% brasileira fundada em 1995, com unidade produtiva em Senador Canedo (GO) e sede em Piracicaba (SP). Especializada na fabricação de thinner industrial e gel coat, além da distribuição de matérias-primas para o setor de compósitos, atende indústrias metalúrgica, automotiva, moveleira, náutica e de construção civil em todo o território nacional.', NULL),
(721, 'A Biovalens S/A é uma empresa de biotecnologia sediada em Rio Verde, Goiás, um dos maiores polos do agronegócio brasileiro. Atua no desenvolvimento e produção de soluções biotecnológicas voltadas para o setor agrícola e industrial. Sua presença em Rio Verde reflete o movimento de atração de empresas de tecnologia avançada para o interior goiano, impulsionado por programas de desenvolvimento econômico municipal.', NULL),
(722, 'Pré-Moldados Santana é uma empresa individual de construção civil localizada em Goiatuba, Goiás, atuando na fabricação e comercialização de elementos pré-moldados de concreto. Produz itens como blocos, postes, vigas e lajes utilizados em obras residenciais e comerciais da região.', NULL),
(724, 'A Artforte Construção Ltda é uma empresa de construção civil estabelecida em Senador Canedo, Goiás, município integrante da região metropolitana de Goiânia. Atua na execução de obras civis, reformas e serviços de construção para o mercado residencial e comercial. A localização estratégica no entorno da capital favorece o acesso a grandes contratos públicos e privados.', NULL),
(727, 'A Vertical Green do Brasil Ltda é uma empresa de engenharia civil sediada no Distrito Agroindustrial de Senador Canedo, Goiás, fundada em 1999. Especializada em soluções sustentáveis de engenharia, atua com reforço de solo, controle de erosão e sistemas de drenagem de águas, com filiais em outros estados e presença consolidada no mercado nacional de obras de infraestrutura.', NULL),
(729, 'A C.A.V Soares Móveis Eireli é uma empresa fabricante e/ou revendedora de móveis sediada em Senador Canedo, Goiás. Atua na produção e comercialização de mobiliário residencial e corporativo para o mercado da grande Goiânia. Oferece soluções em móveis planejados e seriados para clientes finais e revendedores da região metropolitana.', NULL),
(730, 'A Votumix Preparação de Concreto EIRELI é uma empresa especializada na preparação de concreto usinado e massa de argamassa para construção civil, com unidade instalada em Goiatuba, Goiás. Trata-se de filial de uma rede com sede em Votuporanga, São Paulo, que expandiu suas operações para o interior de Goiás, atendendo construtoras e obras da região com fornecimento de concreto pronto.', NULL),
(731, 'A Baruk Laboratórios Ltda, também conhecida como BRK Laboratórios e Fortlife Farmacêutica, é uma empresa farmacêutica fundada em 1988 e sediada no Distrito Agroindustrial de Senador Canedo, Goiás. Atua na fabricação de produtos farmoquímicos e suplementos. É uma das empresas do setor farmacêutico mais antigas do estado, com mais de três décadas de operação.', NULL),
(732, 'Temperos Vó Ita é uma empresa do setor alimentício localizada em Rio Verde, Goiás, dedicada à produção e comercialização de temperos e condimentos artesanais. A marca remete à tradição culinária familiar, oferecendo produtos com sabor caseiro para o mercado local e regional.', NULL),
(735, 'A Lear Indústria e Comércio Ltda, sediada em Rio Verde, Goiás, é parte da Lear Corporation, multinacional americana líder global no fornecimento de sistemas de assentos e sistemas de distribuição elétrica para a indústria automotiva. A empresa fabrica e comercializa interiores automotivos, incluindo conjuntos de bancos, ajustadores, espumas e sistemas de fiação para montadoras.', NULL),
(736, 'A Tecnomont Montagens Industriais Ltda é uma empresa especializada em montagem industrial, fundada em 2009 e sediada em Senador Canedo, Goiás. Atua na execução de obras de infraestrutura e montagem de equipamentos industriais para diversos segmentos, com capital social de R$ 6 milhões e mais de 16 anos de mercado.', NULL),
(739, 'A NASA Soluções Ambientais Ltda é uma empresa licenciada pela SEMAD-GO, sediada no Distrito Agroindustrial de Senador Canedo, Goiás, fundada em 2012. Especializada em logística e gestão de resíduos líquidos e sólidos gerados em processos industriais, é referência regional em saneamento ambiental industrial.', NULL),
(740, 'A Centroeste Ambiental Limpeza Urbana Ltda é uma empresa de serviços ambientais e limpeza urbana sediada em Senador Canedo, Goiás. Presta serviços de coleta de resíduos sólidos, varrição de vias públicas e limpeza de logradouros para municípios da região. Atua como parceira do poder público na gestão dos serviços de saneamento básico e higiene urbana.', NULL),
(743, 'A Partone Hidráulica Ltda é uma empresa localizada em Senador Canedo, Goiás, atuante no segmento de máquinas e equipamentos hidráulicos. Dedica-se ao comércio e serviços de componentes e sistemas hidráulicos para uso industrial e automotivo, atendendo clientes do setor industrial e de manutenção de máquinas pesadas na região metropolitana de Goiânia.', NULL),
(749, 'A Lukatex Indústria e Comércio de Tintas Ltda é uma fabricante de tintas, vernizes, esmaltes e lacas instalada no setor industrial de Senador Canedo, Goiás, desde 2001. Com mais de duas décadas de operação, a empresa produz tintas para uso residencial, comercial e industrial, comercializando seus produtos na região Centro-Oeste.', NULL),
(752, 'A MV Pão de Queijo Indústria e Comércio Ltda é uma empresa do setor alimentício sediada em Senador Canedo, Goiás, dedicada à produção e comercialização de pão de queijo e produtos derivados. O produto é um tradicional item da culinária mineira e goiana, com ampla demanda no mercado regional.', NULL),
(755, 'A Recmed Comércio de Materiais Hospitalares Ltda é uma empresa sediada em Senador Canedo, Goiás, especializada no comércio de materiais e equipamentos hospitalares. Distribui produtos para clínicas, hospitais e laboratórios da região de Goiás, atuando no setor de saúde com foco em insumos médicos e hospitalares.', NULL),
(758, 'A Metalúrgica Sul América Indústria e Comércio Ltda é uma empresa metalúrgica localizada em Senador Canedo, Goiás, atuante na fabricação e comercialização de produtos metálicos para uso industrial e da construção civil. A empresa faz parte do polo industrial do Distrito Agroindustrial de Senador Canedo.', NULL),
(759, 'A Comber Indústria Ltda é uma fabricante de máquinas e equipamentos para as indústrias de alimentos, bebidas e grãos, fundada em 2016 e sediada no Distrito Agroindustrial de Rio Verde II (GO). Integrante do Grupo Comelli, opera duas plantas industriais (Goiás e Santa Catarina) e atende todo o território sul-americano com soluções de automação, secagem de grãos e processos industriais.', NULL),
(766, 'A Sigma Comércio e Serviços Eletromecânicos EIRELI é uma empresa sediada em Senador Canedo, Goiás, atuante na manutenção e comercialização de equipamentos eletromecânicos para uso industrial. Oferece serviços de instalação, reparo e fornecimento de peças e componentes eletromecânicos para indústrias da região.', NULL),
(770, 'A VP Reciclagem Ltda é uma empresa de gestão de resíduos fundada em 2018 e instalada no Distrito Agroindustrial de Senador Canedo, Goiás. Especializada na recuperação e reciclagem de materiais plásticos, a empresa coleta, processa e destina adequadamente resíduos plásticos gerados pela indústria, contribuindo para a economia circular na região metropolitana de Goiânia.', NULL),
(771, 'A Canatec Serviços Ltda é uma empresa de serviços agrícolas sediada no Distrito Agroindustrial de Rio Verde, Goiás, fundada em 2016. Atua na prestação de serviços de preparação de terreno, cultivo e colheita, atendendo produtores rurais do sudoeste goiano. Sua atuação está inserida no dinâmico agronegócio de Rio Verde, uma das regiões produtoras de grãos mais importantes do Brasil.', NULL),
(775, 'A Cooperboi Tecnologia em Nutrição Animal Ltda é uma empresa do agronegócio fundada em 2009 e sediada em Senador Canedo, Goiás. Especializada na fabricação e comercialização de rações balanceadas e alimentos preparados para bovinos, suínos, aves e outros animais, atende produtores rurais e fazendas do Centro-Oeste.', NULL),
(778, 'A Metalúrgica Macedo Ltda é uma empresa do setor metalúrgico estabelecida em Goiatuba, Goiás, atuando na fabricação e comercialização de produtos e estruturas metálicas. Atende demandas da construção civil, do agronegócio e da indústria local com peças soldadas, estruturas e equipamentos sob medida.', NULL),
(786, 'O Condomínio Industrial de Senador Canedo é uma área industrial planejada que abriga empresas de diferentes segmentos em infraestrutura compartilhada no município de Senador Canedo, Goiás. Oferece lotes industriais com infraestrutura básica para instalação de indústrias de pequeno e médio porte. Está inserido no contexto de desenvolvimento industrial da região metropolitana de Goiânia.', NULL),
(791, 'A Metalúrgica Federal Ltda é uma empresa do setor de máquinas e equipamentos localizada em Senador Canedo, Goiás, dedicada à fabricação e manutenção de peças e estruturas metálicas para uso industrial. Sua atuação inclui usinagem, solda e produção de componentes metálicos sob encomenda para empresas do polo industrial de Senador Canedo.', NULL),
(796, 'A Mittel-Klasse Transportadora e Logística Ltda é uma empresa de transporte e logística sediada em Senador Canedo, Goiás, atuante no transporte de cargas e na gestão de operações logísticas para indústrias e comércios da região. Opera no polo industrial de Senador Canedo, prestando serviços de distribuição e movimentação de cargas no Centro-Oeste brasileiro.', NULL),
(798, 'A Parma Produtos Alimentícios Ltda é uma empresa do setor alimentício com mais de 40 anos de história, fundada em 1984 e localizada em Senador Canedo, Goiás. Especializada na fabricação de temperos, molhos, condimentos e misturas para alimentação, atende o mercado varejista e de food service da região Centro-Oeste sob a marca Ki Parma.', NULL),
(803, 'A Nativa Produtos Alimentícios Ltda é uma empresa goiana fundada em 1994, sediada em Senador Canedo, com mais de 30 anos de atuação na fabricação de alimentos naturais e saudáveis. Produz granola, sementes, farinhas e produtos da linha Vida Nativa, comercializados para o varejo, food service e produção de marca própria em todo o estado de Goiás e regiões vizinhas.', NULL),
(806, 'A Jaepel Papéis e Embalagens S.A. é uma indústria de embalagens fundada em 2004 e instalada no Distrito Agroindustrial de Senador Canedo, Goiás. Especializada na fabricação de embalagens de papelão ondulado, a empresa emprega diretamente mais de 700 pessoas e possui certificação FSC® de cadeia de custódia, sendo uma das maiores do setor de papel e embalagens do Centro-Oeste brasileiro.', NULL),
(811, 'A Rio Granito Ltda é uma empresa sediada em Senador Canedo, Goiás, atuante no beneficiamento e comercialização de mármore, granito e pedras ornamentais. Oferece produtos para uso em revestimentos, pisos, tampos e fachadas para o mercado da construção civil na região metropolitana de Goiânia.', NULL),
(815, 'A RGM Visual Ltda é uma empresa localizada em Senador Canedo, Goiás, atuante no segmento de comunicação visual e construção civil. Presta serviços de instalação de fachadas, painéis, placas e elementos visuais para estabelecimentos comerciais e obras da Grande Goiânia.', NULL),
(816, 'A Multiblocos Indústria de Artefatos de Concreto Ltda é uma empresa fabricante de artefatos de concreto localizada em Senador Canedo, Goiás. Produz blocos, pavers, meios-fios, lajotas e outros elementos de concreto utilizados em obras de construção civil e urbanização, atendendo construtoras, prefeituras e empreiteiras da região metropolitana de Goiânia.', NULL),
(818, 'A Incinera Tratamento de Resíduos Ltda é uma empresa especializada em gestão ambiental e incineração de resíduos, fundada em 2005 e sediada em Senador Canedo, Goiás. Certificada pela ISO 9001:2015, oferece serviços de incineração de resíduos industriais, químicos, farmacêuticos e hospitalares, com capacidade de processamento de 3.600 toneladas por mês.', NULL),
(824, 'A Quatar Participações Ltda é uma empresa do setor moveleiro sediada em Senador Canedo, Goiás, atuante na fabricação ou comercialização de móveis e produtos correlatos para o mercado regional. Integra o polo industrial de Senador Canedo, atendendo clientes do varejo e do setor de construção civil da Grande Goiânia.', NULL),
(826, 'A SP Indústria de Móveis Ltda é uma empresa fabricante de móveis estabelecida em Senador Canedo, Goiás, produzindo peças para uso residencial, comercial e corporativo. Atua no abastecimento do mercado moveleiro da região metropolitana de Goiânia, contribuindo para a geração de emprego e renda no município.', NULL),
(827, 'A Cerâmica Pontalina Ltda ME é uma microempresa fabricante de produtos cerâmicos para a construção civil, sediada em Pontalina, Goiás. Produz tijolos, telhas e outros itens cerâmicos estruturais utilizados em edificações residenciais e rurais. Abastece o mercado de material de construção da região sul goiana, aproveitando a disponibilidade de argila da região.', NULL),
(829, 'A Valeiro & Bessa Indústria Química Ltda é uma empresa do setor químico localizada em Pontalina, Goiás, dedicada à fabricação e comercialização de produtos químicos industriais. Atende empresas de diversos segmentos que demandam insumos e produtos químicos para seus processos produtivos, operando no Distrito Industrial de Pontalina.', NULL),
(835, 'A Plastem Indústria e Comércio de Artefatos Plásticos Ltda é uma empresa fundada em 2005 e sediada em Senador Canedo, Goiás, especializada na fabricação de embalagens e artefatos plásticos. Produz embalagens plásticas diversas para uso industrial e comercial, atendendo clientes da região metropolitana de Goiânia.', NULL),
(841, 'A Angelo Auricchio Companhia Ltda, conhecida comercialmente como Conservas Olé, é uma grande indústria alimentícia fundada em 1993 e localizada no Distrito Agroindustrial de Morrinhos, Goiás. Especializada na fabricação de conservas vegetais, incluindo palmito, legumes, frutas, temperos, molhos e condimentos. Com capital de R$ 50 milhões, é uma das principais indústrias de conservas do Centro-Oeste brasileiro.', NULL),
(846, 'A Ecoplast Indústria e Comércio de PVC Ltda é uma empresa fundada em 2007 e instalada no Distrito Industrial de Morrinhos, Goiás, especializada na fabricação de artefatos de PVC para uso na construção civil. Produz telhas, forros, caixas de descarga e outros componentes plásticos utilizados em edificações.', NULL),
(847, 'A Rural Forte Nutrição Animal Ltda é uma empresa do agronegócio fundada em 2003 e sediada em Pontalina, Goiás, com foco na fabricação e comercialização de rações e nutrição animal para o setor rural. Possui linha própria de produtos e é referência no varejo agropecuário da região, atendendo produtores rurais e fazendas do sul goiano.', NULL),
(853, 'O Condomínio Tecnológico de Pontalina é uma área industrial organizada destinada à instalação de empresas de médio e pequeno porte no município de Pontalina, Goiás. Disponibiliza lotes com infraestrutura adequada para o desenvolvimento de atividades industriais e tecnológicas na região sul do estado. Funciona como polo de atração de investimentos para o município.', NULL),
(856, 'A LF Comércio de Grãos Ltda-ME é uma empresa de pequeno porte localizada em Pontalina, Goiás, atuante na compra e venda de grãos como soja, milho e sorgo produzidos na região. Integra a cadeia comercial do agronegócio do sul goiano, conectando produtores rurais a traders e processadoras de grãos.', NULL),
(857, 'A Brasquímica Produtos Asfálticos Ltda é uma empresa industrial sediada em Morrinhos, Goiás, especializada na fabricação e distribuição de produtos asfálticos utilizados em pavimentação e impermeabilização. Fornece emulsões asfálticas, asfalto modificado e afins para construtoras, prefeituras e obras de infraestrutura viária. Atende principalmente o mercado do Centro-Oeste brasileiro.', NULL),
(859, 'O Bras Garcia - Ferro Velho Tigrão é uma empresa de reciclagem e comércio de sucatas metálicas sediada em Pontalina, Goiás. Atua na coleta, triagem e comercialização de ferro-velho, metais e materiais recicláveis. Contribui para a cadeia de reciclagem regional, fornecendo matéria-prima secundária para indústrias metalúrgicas e siderúrgicas.', NULL),
(860, 'A Cooperativa Mista dos Produtores Rurais de Pontalina (COMPROP) é uma cooperativa agropecuária fundada em 2013 e sediada em Pontalina, Goiás, com foco principal no comércio atacadista de leite e derivados. Reúne produtores rurais da região para comercialização conjunta de produtos agropecuários, fortalecendo a agricultura familiar e patronal local.', NULL),
(861, 'A Pontal Pontalina Alimentos Ltda é uma empresa do setor alimentício fundada em 1993, localizada em Pontalina, Goiás, com atuação na fabricação de farinha de milho e seus derivados. Com mais de três décadas de atividade, a empresa atende o mercado regional com produtos à base de milho amplamente utilizados na alimentação humana.', NULL),
(862, 'Júnio Cezar Ferreira da Silva é um profissional autônomo ou microempreendedor individual do ramo metalúrgico estabelecido em Pontalina, Goiás. Presta serviços de serralheria, soldagem e fabricação de estruturas metálicas para clientes da região.', NULL),
(863, 'A Blocos Edificar Ltda é uma empresa fabricante de blocos de concreto e outros artefatos para construção civil, sediada em Morrinhos, Goiás. Produz blocos estruturais, pavimentadores e complementos destinados a obras residenciais, comerciais e de infraestrutura. Atende construtoras e lojas de material de construção da região sul do estado.', NULL),
(869, 'A Votumix Preparação de Concreto EIRELI mantém uma unidade em Morrinhos, Goiás, atuando na preparação e fornecimento de concreto usinado para obras da construção civil na região. Trata-se de filial da rede Votumix, originária de Votuporanga, São Paulo, com operações distribuídas pelo interior de Goiás.', NULL),
(870, 'A Cooperativa Mista de Produtores de Leite de Morrinhos (COMPLEM) é uma cooperativa leiteira fundada em 1994 e sediada em Morrinhos, Goiás, com atuação no processamento e comercialização de leite e derivados. Opera em Morrinhos e em outros 13 municípios estratégicos da região, sendo responsável pela geração de renda e emprego no setor lácteo do sul goiano.', NULL),
(876, 'A Cooperativa Mista de Produtores de Leite de Morrinhos (COMPLEM) é uma cooperativa leiteira com mais de 30 anos de história, sediada em Morrinhos, Goiás, dedicada à fabricação de laticínios e ao fortalecimento da cadeia produtiva do leite na região. Reúne produtores rurais de Morrinhos e municípios vizinhos, processando e comercializando leite e derivados com padrão de qualidade.', NULL),
(878, 'A Cooperativa Mista de Produtores de Leite de Morrinhos (COMPLEM) possui diferentes unidades e registros operacionais que refletem sua estrutura produtiva diversificada no sul de Goiás. Seu modelo cooperativista beneficia centenas de famílias produtoras de leite da microrregião, industrializando e comercializando leite e derivados.', NULL),
(879, 'A Martins e Casserley Ltda é uma empresa do agronegócio localizada em Rio Verde, Goiás, um dos maiores polos agrícolas do Brasil. Atua no comércio e prestação de serviços voltados ao setor rural, possivelmente envolvendo insumos agrícolas, máquinas ou consultoria agropecuária.', NULL),
(881, 'A Líder Telhas de Concreto Ltda é uma empresa fabricante de telhas e artefatos de concreto localizada em Rio Verde, Goiás. Produz telhas de concreto para uso residencial e comercial, além de outros elementos pré-moldados utilizados na construção civil, atendendo o mercado da região sudoeste goiana.', NULL),
(882, 'A Cooperativa Mista de Produtores de Leite de Morrinhos (COMPLEM) é uma das principais organizações cooperativistas do sul de Goiás, reunindo produtores leiteiros para processamento e comercialização de laticínios. Com unidades e registros múltiplos que refletem suas diferentes linhas de atividade, a cooperativa produz queijos, iogurtes, leite pasteurizado e outros derivados.', NULL),
(883, 'A Zincar é uma empresa especializada em galvanização e zincagem de peças e componentes metálicos, sediada em Aparecida de Goiânia, Goiás. Realiza o processo de revestimento metálico por zincagem a fogo ou eletrolítica, protegendo estruturas de aço contra corrosão para os setores de construção civil, agronegócio e indústria. É referência regional no tratamento de superfícies metálicas na grande Goiânia.', NULL),
(884, 'A AFA do Brasil Ltda é uma empresa de construção civil sediada em Rio Verde, Goiás, atuando na execução de obras residenciais, comerciais e industriais. Oferece serviços de engenharia civil, edificações e projetos de infraestrutura para o mercado do sudoeste goiano. Rio Verde, polo agroindustrial de destaque, representa um mercado em constante expansão para o setor da construção.', NULL),
(885, 'A CERR - Facilita Tintas, vinculada à Total Formulários, é uma empresa sediada em Aparecida de Goiânia, Goiás, atuante na comercialização e formulação de tintas e produtos correlatos. Oferece soluções em pinturas residenciais, comerciais e industriais para o mercado da grande Goiânia. Distribui marcas de tintas e presta assessoria técnica a pintores, construtoras e clientes finais.', NULL),
(886, 'A Andrade &amp; Vilela Artefatos de Cimento Ltda é uma empresa fabricante de artefatos de cimento e concreto pré-moldado, sediada em Rio Verde, Goiás. Produz itens como blocos, lajes, manilhas, meio-fio e outros componentes utilizados na construção civil. Atende construtoras, prefeituras e clientes particulares no sudoeste goiano.', NULL),
(887, 'A Marsam do Brasil é uma empresa industrial sediada em Aparecida de Goiânia, Goiás, atuante na fabricação de produtos manufaturados para o mercado regional e nacional. Integra o Distrito Agroindustrial de Aparecida de Goiânia, que concentra diversas indústrias de transformação do estado. Destaca-se pela sua contribuição para a geração de empregos e o desenvolvimento econômico local.', NULL),
(888, 'A Milano Temper Vidros e Esquadrias de Alumínios é uma empresa especializada na fabricação e instalação de vidros temperados e esquadrias de alumínio, sediada em Aparecida de Goiânia, Goiás. Produz portas, janelas, fachadas e divisórias em alumínio e vidro para o mercado da construção civil da grande Goiânia. Atende construtoras, arquitetos e clientes finais com soluções em alumínio e vidro de alta qualidade.', NULL),
(890, 'A Maravalha Rio Verde Ltda é uma empresa madereira localizada no Distrito Agroindustrial de Rio Verde, Goiás, especializada na produção e comercialização de maravalha (aparas de madeira resultantes do processo de serragem). O produto é amplamente utilizado no agronegócio como cama de frango, suínos, bovinos e equinos, atendendo fazendas e integradoras do setor de avicultura e pecuária da região Centro-Oeste.', NULL),
(891, 'A Gonçalves Silva Pneus Ltda é uma empresa do setor automobilístico localizada em Rio Verde, Goiás, atuante na comercialização e serviços de pneus para veículos leves, pesados e máquinas agrícolas. Atende produtores rurais, transportadoras e motoristas da região, que é um importante entroncamento logístico do agronegócio no Centro-Oeste.', NULL),
(892, 'A Velgo Indústria e Comércio de Móveis Ltda é uma fabricante de móveis metálicos localizada no Distrito Agroindustrial de Aparecida de Goiânia (DAIAG), em Goiás. Com mais de 35 anos de trajetória, produz mobiliário em metal para uso residencial, comercial e industrial.', NULL),
(893, 'A Metalúrgica e Serralheria Rio Verde Ltda é uma empresa do setor metalúrgico estabelecida em Rio Verde, Goiás, dedicada à fabricação de estruturas metálicas, portões, grades, coberturas e outros produtos de serralheria. Atende o mercado da construção civil, do agronegócio e da indústria local com soluções em metal sob encomenda.', NULL),
(894, 'A Midiz Indústria e Comércio de Fraldas S.A. é uma fabricante de fraldas descartáveis, conhecida pela marca Kisses, localizada no Distrito Agroindustrial de Aparecida de Goiânia (DAIAG). Fundada em 2004, a empresa passou por processo de recuperação judicial. Atua no segmento de higiene infantil e descartáveis, distribuindo seus produtos em redes varejistas da região Centro-Oeste e de outros estados.', NULL),
(895, 'A Camil Alimentos S.A. é uma das maiores empresas brasileiras de alimentos, especializada no processamento, embalagem e distribuição de arroz e feijão, além de marcas como Açúcar União, Coqueiro, Santa Amália e Mabel. A unidade de Aparecida de Goiânia (GO), instalada no Distrito Agroindustrial desde 2018, realiza o beneficiamento de arroz para o mercado nacional.', NULL),
(897, 'A Recycle Indústria e Comércio de Recicláveis Ltda é uma empresa do setor de reciclagem sediada em Aparecida de Goiânia, Goiás. Atua na coleta, processamento e comercialização de materiais recicláveis como plásticos, metais, papel e vidro. Contribui para a cadeia de economia circular na grande Goiânia, fornecendo matéria-prima secundária para indústrias de transformação.', NULL),
(899, 'A Belma Industrial de Gêneros Alimentícios Ltda é uma indústria alimentícia fundada em 2006, localizada no Distrito Agroindustrial de Aparecida de Goiânia (GO). Sua atividade principal é a fabricação de biscoitos e bolachas, com operações também voltadas à produção de massas alimentícias e derivados de panificação.', NULL),
(900, 'A Gynglass Vidros e Esquadrias Ltda é uma empresa do setor de vidros e esquadrias sediada em Aparecida de Goiânia, Goiás, atuante no fornecimento de vidros temperados e esquadrias para uso residencial e comercial. A empresa operou no Distrito Agroindustrial de Aparecida de Goiânia (DAIAG) e teve suas atividades relacionadas ao mercado de vidraçaria na região metropolitana de Goiânia. Parte de suas operações foi transferida para outra empresa do setor, a Tempervidros.', NULL),
(901, 'A Contel Obras e Serviços Ltda é uma empresa de construção civil e serviços de engenharia sediada no Distrito Agroindustrial de Aparecida de Goiânia (DAIAG). Com mais de 47 anos de experiência, atua em obras de fundação, estruturas metálicas, serviços de telecom e reforço estrutural. Fornece soluções para torres autoportantes, estruturas para painéis fotovoltaicos e manutenção de sites de telecomunicação.', NULL),
(902, 'A Transbel Transportes e Logística Eireli é uma empresa de transporte rodoviário de carga fundada em 2013, localizada no Polo Empresarial Goiás, em Aparecida de Goiânia. Atua no transporte intermunicipal, interestadual e internacional de mercadorias, oferecendo soluções logísticas para indústrias e comércio da região metropolitana de Goiânia.', NULL),
(903, 'A Cruzeiro Elaboração de Produtos Diversificados Ltda é uma indústria localizada no Distrito Agroindustrial de Aparecida de Goiânia (DAIAG), atuante na fabricação de cosméticos, perfumes e produtos de higiene pessoal. Fundada em 1996, faz parte do Grupo Cruzeiro, que desde 1963 se dedica à fabricação e comercialização de produtos químicos industriais. A empresa também atua nos segmentos de produtos saneantes e embalagens.', NULL),
(907, 'A Cruzeiro Industrial Química Gomes Ltda é uma indústria química do Grupo Cruzeiro, estabelecida no Distrito Agroindustrial de Aparecida de Goiânia (DAIAG), Goiás. Fundada em 2002, ocupa uma área superior a 6.000 m² e se especializa na fabricação de cosméticos, produtos de limpeza e higiene pessoal. O grupo atua no mercado desde 1963 e fornece insumos químicos para diversos segmentos industriais.', NULL),
(910, 'A CVL Têmpera de Vidros Ltda é uma empresa especializada no beneficiamento de vidros temperados e laminados, sediada em Aparecida de Goiânia, Goiás. Realiza o processo de têmpera que confere maior resistência ao vidro, fornecendo produto acabado para construtoras, instaladores e o mercado de alumínio e vidro da grande Goiânia. Atende tanto clientes industriais quanto residenciais.', NULL),
(913, 'A Nutrien Soluções Agrícolas Ltda é a divisão brasileira da Nutrien, maior produtora de fertilizantes do mundo, com unidade instalada no Distrito Agroindustrial de Morrinhos, Goiás. No Brasil, a empresa opera como uma das maiores distribuidoras de insumos agrícolas, com mais de 24 lojas e mais de 200 consultores técnicos atendendo centenas de municípios nos estados de São Paulo, Minas Gerais e Goiás.', NULL),
(917, 'A Apoliveira Com de Secos e Molhados Ltda, conhecida pela marca Lukgeo, é uma empresa comercial sediada em Morrinhos, Goiás, atuante no segmento de distribuição e comércio de alimentos secos e molhados. Abastece o varejo local com produtos alimentícios de ampla variedade. Sua atuação está voltada ao abastecimento de mercados, mercearias e estabelecimentos da região sul goiana.', NULL)
